insert into academy.entry_categories (entry_id,category_id,position) values ('ai-ecosystem-fundamentals','00',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('ai-ecosystem-fundamentals','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: מערכת בקשות ציוד מחלצת טקסט ל־DTO; קוד רגיל מאמת מלאי והרשאות. מפו ספק, מודל, endpoint, SDK ו־trace, והשוו retrieval לנוהל מתעדכן מול שינוי משקלים.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','React יכול לפנות ל־ASP.NET ול־SQL קיימים; קריאת API אינה מחייבת מעבר שרת ל־Python.','כלל עסקי או SQL עשויים להספיק. פרקי RAG, inference ואימון מרחיבים את המפה בלי לשכפל ספקים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ai-ecosystem-fundamentals',0,'תפקיד וזרימת עבודה','התחילו מהבעיה: חישוב, חיפוש, סיווג, יצירה או פעולה. מחזור המערכת כולל נתונים, אימון, תוצר, הסקה, יישום והערכה. מודל הוא רכיב אחד לצד בדיקות, הרשאות ותפעול; ML קלאסי אינו מחייב LLM.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ai-ecosystem-fundamentals',1,'מיקום במסלול הלמידה','מסלול מרכזי: מפה לפני בחירת מוצר, אחריה יסודות LLM וקריאת Model Card. RAG, הרצה מקומית ואימון הן הסתעפויות לפי צורך.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ai-ecosystem-fundamentals',2,'שילוב ב־C#/.NET','React יכול לפנות ל־ASP.NET ול־SQL קיימים; קריאת API אינה מחייבת מעבר שרת ל־Python.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ai-ecosystem-fundamentals',3,'יתרונות ומתי לבחור','מפה חוצה ספקים עוזרת להעריך כלי חדש ולצמצם רכיבים מיותרים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ai-ecosystem-fundamentals',4,'מגבלות, רישוי ונתונים','היכרות מושגית אינה ניסיון תפעולי. RAG אינו תמיד עדיף על tuning; רישיון SDK אינו רישיון משקלים או נתונים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ai-ecosystem-fundamentals',5,'השוואה לחלופות','כלל עסקי או SQL עשויים להספיק. פרקי RAG, inference ואימון מרחיבים את המפה בלי לשכפל ספקים.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('ai-ecosystem-fundamentals','must_learn','ידע יסוד מאפשר לבחור שכבה וטכנולוגיה לפי בעיה, בלי לערבב פופולריות עם התאמה.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('ai-ecosystem-fundamentals','מפת AI, ML, Deep Learning ו־GenAI והבחנה בין מודל, ספק, SDK, מסגרת, פרוטוקול ומנוע הרצה.','React יכול לפנות ל־ASP.NET ול־SQL קיימים; קריאת API אינה מחייבת מעבר שרת ל־Python.','not_applicable','פרק מושגי ללא מאגר מוצר.','2026-11-03');
insert into academy.entry_language_labels (entry_id,position,label) values ('ai-ecosystem-fundamentals',0,'ידע מושגי — אינו SDK');
