insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('agentic-coding-fundamentals','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: תקנו ולידציה בטופס React וב־ASP.NET endpoint: הגדירו שלושה תנאי קבלה, גבולות כתיבה ובדיקת בקשה ישירה לשרת. סקרו diff והריצו בדיקות לפני שמירה או פרסום.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','אפשר לעבוד על קוד C# ו־React; הרצת dotnet build/test דורשת SDK ותלויות בסביבת העבודה. עריכת C# אינה SDK .NET של העוזר.','שינוי ידני קטן הוא baseline ראוי. Copilot מתאים לבחינת Visual Studio; Codex או Claude Code למסלול סוכני, ו־Cursor להשוואת IDE.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agentic-coding-fundamentals',0,'תפקיד וזרימת עבודה','כתבו reproduction ותנאי קבלה לפני העברת משימה. סוכן יכול לקרוא, לערוך ולהריץ כלים בהתאם לתצורה. אישור פעולה, בידוד מערכת וסקירת תוצאה הם שלושה דברים שונים; הצלחת פקודה אינה הוכחת נכונות עסקית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agentic-coding-fundamentals',1,'מיקום במסלול הלמידה','מסלול מרכזי לפני מוצר: בחרו עוזר אחד לתרגיל מלא. חלופה נוספת משמשת להשוואה בלבד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agentic-coding-fundamentals',2,'שילוב ב־C#/.NET','אפשר לעבוד על קוד C# ו־React; הרצת dotnet build/test דורשת SDK ותלויות בסביבת העבודה. עריכת C# אינה SDK .NET של העוזר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agentic-coding-fundamentals',3,'יתרונות ומתי לבחור','תנאי קבלה וגבולות פעולה מאפשרים סקירה ובדיקה חוזרת בכל עורך.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agentic-coding-fundamentals',4,'מגבלות, רישוי ונתונים','קוד וקלט חיצוניים אינם מהימנים; עלות, גישה לרשת ונתונים תלויים בסביבה ובחשבון. checkpoints אינם גיבוי Git.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agentic-coding-fundamentals',5,'השוואה לחלופות','שינוי ידני קטן הוא baseline ראוי. Copilot מתאים לבחינת Visual Studio; Codex או Claude Code למסלול סוכני, ו־Cursor להשוואת IDE.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('agentic-coding-fundamentals','must_learn','המיומנות הניידת היא הגדרת משימה ובדיקת השינוי, ולא היכרות עם כל עוזר בשוק.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('agentic-coding-fundamentals','תהליך עבודה עם עוזר קוד: משימה תחומה, הקשר, הרשאות, diff ובדיקות לפני קבלת שינוי.','אפשר לעבוד על קוד C# ו־React; הרצת dotnet build/test דורשת SDK ותלויות בסביבת העבודה. עריכת C# אינה SDK .NET של העוזר.','not_applicable','פרק מושגי ללא מאגר מוצר.','2026-11-03');
insert into academy.entry_language_labels (entry_id,position,label) values ('agentic-coding-fundamentals',0,'ידע מושגי — כל שפת פרויקט');
