insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('github-copilot','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: תקנו ולידציה בטופס React וב־ASP.NET endpoint: הגדירו שלושה תנאי קבלה, גבולות כתיבה ובדיקת בקשה ישירה לשרת. סקרו diff והריצו בדיקות לפני שמירה או פרסום.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','קיים שילוב Visual Studio רשמי לעבודה על פתרונות .NET. יכולת IDE אינה SDK לבניית סוכנים בתוך היישום.','Codex ו־Claude Code מציעים חלופות למשימה תחומה; GitHub MCP Server הוא חיבור כלים, לא אותו מוצר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('github-copilot',0,'תפקיד וזרימת עבודה','השלמה, שיחה וסוכן הם מצבי עבודה נפרדים. יכולות משתנות לפי IDE, גרסה וחשבון; מטריצת היכולות הרשמית מסומנת Public Preview ואינה הבטחת שוויון בין עורכים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('github-copilot',1,'מיקום במסלול הלמידה','בחירה אפשרית לעוזר היחיד בתרגיל המרכזי, במיוחד ב־Visual Studio; אין צורך לתרגל גם את כל החלופות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('github-copilot',2,'שילוב ב־C#/.NET','קיים שילוב Visual Studio רשמי לעבודה על פתרונות .NET. יכולת IDE אינה SDK לבניית סוכנים בתוך היישום.');
insert into academy.entry_sections (entry_id,position,title,body) values ('github-copilot',3,'יתרונות ומתי לבחור','אפשר לתרגל עזרה בקוד בלי להחליף את סביבת Visual Studio המוכרת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('github-copilot',4,'מגבלות, רישוי ונתונים','מוצר מסחרי עם יכולות והרשאות לפי מסלול. מטריצת תכונות Preview אינה מעידה שכל Copilot הוא Preview; אין הנחת רישיון self-host או פרטיות לכל חשבון.');
insert into academy.entry_sections (entry_id,position,title,body) values ('github-copilot',5,'השוואה לחלופות','Codex ו־Claude Code מציעים חלופות למשימה תחומה; GitHub MCP Server הוא חיבור כלים, לא אותו מוצר.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('github-copilot','should_know','כדאי להכיר כנתיב מעשי בתוך סביבת .NET קיימת.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('github-copilot','עוזר פיתוח להשלמה, שיחה ומשימות סוכן ב־IDE וב־GitHub, עם נתיב Visual Studio למפתחי .NET.','קיים שילוב Visual Studio רשמי לעבודה על פתרונות .NET. יכולת IDE אינה SDK לבניית סוכנים בתוך היישום.','not_applicable','אין מאגר מוצר ציבורי מייצג שנבחר; אין ייחוס Stars של SDK לכל השירות.','2026-11-03');
