insert into academy.entry_categories (entry_id,category_id,position) values ('cline','01',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('cline','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: תקנו ולידציה בטופס React וב־ASP.NET endpoint: הגדירו שלושה תנאי קבלה, גבולות כתיבה ובדיקת בקשה ישירה לשרת. סקרו diff והריצו בדיקות לפני שמירה או פרסום. בדקו תצורת Auto Approve וספק לפני הרצה.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','אפשר לעבוד על קוד C# ו־React; הרצת dotnet build/test דורשת SDK ותלויות בסביבת העבודה. עריכת C# אינה SDK .NET של העוזר.','השוו לעוזר הקיים באותה משימה; Aider ממוקד terminal/Git, ו־Copilot באינטגרציית IDE.');
insert into academy.entry_sections (entry_id,position,title,body) values ('cline',0,'תפקיד וזרימת עבודה','Cline פועל בממשקי פיתוח ומתפעל קבצים וכלים. Auto Approve מוגדר לפי קטגוריות; אין להניח שכל פקודה דורשת אישור בכל תצורה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('cline',1,'מיקום במסלול הלמידה','אופציונלי — להשוואה, העשרה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי ואין חובה לתרגל אותו. בחרו בו כשבחירת provider ותצורת אישורים הן מטרת ההשוואה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('cline',2,'שילוב ב־C#/.NET','אפשר לעבוד על קוד C# ו־React; הרצת dotnet build/test דורשת SDK ותלויות בסביבת העבודה. עריכת C# אינה SDK .NET של העוזר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('cline',3,'יתרונות ומתי לבחור','בחירת ספק ותצורה גלויה מסייעות להשוות תהליך עבודה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('cline',4,'מגבלות, רישוי ונתונים','Apache 2.0 לקוד אינו תנאי ספקי המודל או Enterprise. בחירת ספק אינה הבטחת data locality; סיווג פקודה כבטוחה אינו הרשאה עסקית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('cline',5,'השוואה לחלופות','השוו לעוזר הקיים באותה משימה; Aider ממוקד terminal/Git, ו־Copilot באינטגרציית IDE.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('cline','should_know','חלופה משמעותית לבחינת קוד פתוח ושליטה בספק, בלי צורך בעוזר נוסף במסלול המרכזי. אופציונלי להשוואה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('cline','עוזר קוד פתוח עם בחירת ספקי מודלים ובקרות אישור לפעולות.','אפשר לעבוד על קוד C# ו־React; הרצת dotnet build/test דורשת SDK ותלויות בסביבת העבודה. עריכת C# אינה SDK .NET של העוזר.','unverified','זהות המאגר לפי המקור הרשמי; מדידה חסרה אינה אפס. אין head/latest מאומת מהמחקר.','2026-11-03');
