insert into academy.entry_categories (entry_id,category_id,position) values ('google-antigravity','01',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('google-antigravity','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: תקנו ולידציה בטופס React וב־ASP.NET endpoint: הגדירו שלושה תנאי קבלה, גבולות כתיבה ובדיקת בקשה ישירה לשרת. סקרו diff והריצו בדיקות לפני שמירה או פרסום. בחרו ממשק אחד ותעדו מצב אישור וזמינות התכונה.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','אפשר לעבוד על קוד C# ו־React; הרצת dotnet build/test דורשת SDK ותלויות בסביבת העבודה. עריכת C# אינה SDK .NET של העוזר. לא אומת SDK C# מקומי של המוצר.','השוו ל־Codex או Cursor לפי אופן העבודה. מעבר צרכני Gemini CLI אינו הצדקה לרשומת Gemini נוספת בלי בירור זכאות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('google-antigravity',0,'תפקיד וזרימת עבודה','CLI ואפליקציה הם ממשקים של אותו מוצר ברשומה זו. יש להבחין deny/ask/allow מבידוד; מצבי Auto מסוימים מתועדים כ־Preview ותלויים בגרסה, מערכת הפעלה וחשבון.');
insert into academy.entry_sections (entry_id,position,title,body) values ('google-antigravity',1,'מיקום במסלול הלמידה','אופציונלי — להשוואה, העשרה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי ואין חובה לתרגל אותו. חלופה למי שבוחר סביבת Google; אין צורך להוסיף CLI נוסף לתרגיל שכבר הושלם.');
insert into academy.entry_sections (entry_id,position,title,body) values ('google-antigravity',2,'שילוב ב־C#/.NET','אפשר לעבוד על קוד C# ו־React; הרצת dotnet build/test דורשת SDK ותלויות בסביבת העבודה. עריכת C# אינה SDK .NET של העוזר. לא אומת SDK C# מקומי של המוצר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('google-antigravity',3,'יתרונות ומתי לבחור','מסלול אחד מאפשר להכיר עבודה סוכנית בממשקי Google.');
insert into academy.entry_sections (entry_id,position,title,body) values ('google-antigravity',4,'מגבלות, רישוי ונתונים','תנאי השירות והחשבון נפרדים מיכולות העורך. Preview של מצב Auto אינו סטטוס כל המוצר; אין הבטחת שוויון CLI ואפליקציה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('google-antigravity',5,'השוואה לחלופות','השוו ל־Codex או Cursor לפי אופן העבודה. מעבר צרכני Gemini CLI אינו הצדקה לרשומת Gemini נוספת בלי בירור זכאות.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('google-antigravity','should_know','כדאי להכיר חלופת Google ואת גבולות הממשקים וההרשאות. אופציונלי להשוואה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('google-antigravity','סביבת Google לעבודה עם סוכני פיתוח, עם ממשקי אפליקציה ו־CLI ובקרות הרשאות לפי מסלול.','אפשר לעבוד על קוד C# ו־React; הרצת dotnet build/test דורשת SDK ותלויות בסביבת העבודה. עריכת C# אינה SDK .NET של העוזר. לא אומת SDK C# מקומי של המוצר.','not_applicable','אין מאגר מוצר ציבורי מייצג שנבחר; אין ייחוס Stars של SDK לכל השירות.','2026-11-03');
