insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('devin-desktop','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: תקנו ולידציה בטופס React וב־ASP.NET endpoint: הגדירו שלושה תנאי קבלה, גבולות כתיבה ובדיקת בקשה ישירה לשרת. סקרו diff והריצו בדיקות לפני שמירה או פרסום. השוו גבולות local/cloud וסקירת משימה אחת, בלי להפעיל צוות סוכנים אוטומטית.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','אפשר לעבוד על קוד C# ו־React; הרצת dotnet build/test דורשת SDK ותלויות בסביבת העבודה. עריכת C# אינה SDK .NET של העוזר.','Cursor הוא חלופת IDE; Codex ו־Claude Code יכולים לשמש עוזרים למשימה תחומה. אין רשומת Windsurf שנייה ואין סימון Discontinued למוצר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('devin-desktop',0,'תפקיד וזרימת עבודה','הודעת Cognition מ־2 ביוני 2026 מאמתת את שינוי השם והמשך בסיס ה־IDE. תיעוד Cascade מסמן רכיב Legacy; אין להסיק מכך ש־Devin Desktop הופסק. סוכן ו־command center הם רכיבים נפרדים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('devin-desktop',1,'מיקום במסלול הלמידה','אופציונלי — להשוואה, העשרה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי ואין חובה לתרגל אותו. השוואת סביבת עבודה וניהול משימות, אחרי השלמת תרגיל בעוזר אחד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('devin-desktop',2,'שילוב ב־C#/.NET','אפשר לעבוד על קוד C# ו־React; הרצת dotnet build/test דורשת SDK ותלויות בסביבת העבודה. עריכת C# אינה SDK .NET של העוזר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('devin-desktop',3,'יתרונות ומתי לבחור','ממשק משותף יכול לעזור לסקור משימות וסוכנים ממקורות שונים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('devin-desktop',4,'מגבלות, רישוי ונתונים','מוצר ושירותים מסחריים; הרשאות ומדיניות נתונים תלויות מסלול. רישוי פרוטוקול פתוח אינו רישיון כל המוצר; rebrand אינו תאריך ההשקה הראשון.');
insert into academy.entry_sections (entry_id,position,title,body) values ('devin-desktop',5,'השוואה לחלופות','Cursor הוא חלופת IDE; Codex ו־Claude Code יכולים לשמש עוזרים למשימה תחומה. אין רשומת Windsurf שנייה ואין סימון Discontinued למוצר.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('devin-desktop','should_know','חלופת IDE משמעותית עם זהות מוצר מאומתת; Windsurf נשמרת בשם ובחיפוש ללא כפילות. אופציונלי להשוואה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('devin-desktop','Devin Desktop, לשעבר Windsurf: סביבת IDE וניהול משימות סוכנים מקומיים ובענן ברשומה אחת.','אפשר לעבוד על קוד C# ו־React; הרצת dotnet build/test דורשת SDK ותלויות בסביבת העבודה. עריכת C# אינה SDK .NET של העוזר.','not_applicable','אין מאגר מוצר ציבורי מייצג שנבחר; אין ייחוס Stars של SDK לכל השירות.','2026-11-03');
