insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('aider','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: תקנו ולידציה בטופס React וב־ASP.NET endpoint: הגדירו שלושה תנאי קבלה, גבולות כתיבה ובדיקת בקשה ישירה לשרת. סקרו diff והריצו בדיקות לפני שמירה או פרסום. בתרגיל ללא אישור Commit בטלו auto-commits ו־dirty-commits מראש.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','המימוש ב־Python; טבלת השפות מתעדת C# וקובצי .cs. זו עריכת קוד, לא SDK .NET.','Cline מדגיש תצורה וספקים; Codex או Claude Code מספקים חלופות למשימות פיתוח רחבות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('aider',0,'תפקיד וזרימת עבודה','מפת המאגר מסייעת בהקשר קוד, והשינויים משתלבים בזרימת Git. מנגנוני auto-commit ושמירת dirty changes ניתנים להגדרה ואינם אישור לשמור בשם המשתמש.');
insert into academy.entry_sections (entry_id,position,title,body) values ('aider',1,'מיקום במסלול הלמידה','אופציונלי — להשוואה, העשרה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי ואין חובה לתרגל אותו. התמחות terminal/Git; אין צורך להחליף עוזר מרכזי שכבר מתאים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('aider',2,'שילוב ב־C#/.NET','המימוש ב־Python; טבלת השפות מתעדת C# וקובצי .cs. זו עריכת קוד, לא SDK .NET.');
insert into academy.entry_sections (entry_id,position,title,body) values ('aider',3,'יתרונות ומתי לבחור','קישור מפורש בין הקשר מאגר לשינויי Git מתאים להשוואת patch קטן.');
insert into academy.entry_sections (entry_id,position,title,body) values ('aider',4,'מגבלות, רישוי ונתונים','Apache 2.0 לקוד נפרד מתנאי המודל. יש לבדוק התנהגות commit, hooks וסודות לפני שימוש.');
insert into academy.entry_sections (entry_id,position,title,body) values ('aider',5,'השוואה לחלופות','Cline מדגיש תצורה וספקים; Codex או Claude Code מספקים חלופות למשימות פיתוח רחבות.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('aider','enrichment','העשרה להבנת workflow ממוקד patch ומאגר. אופציונלי להשוואה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('aider','עוזר תכנות במסוף עם מפת מאגר ואינטגרציית Git.','המימוש ב־Python; טבלת השפות מתעדת C# וקובצי .cs. זו עריכת קוד, לא SDK .NET.','unverified','זהות המאגר לפי המקור הרשמי; מדידה חסרה אינה אפס. אין head/latest מאומת מהמחקר.','2026-11-03');
