insert into academy.entry_categories (entry_id,category_id,position) values ('agent-systems-fundamentals','02',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('agent-systems-fundamentals','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: get_stock מחזיר מידע; reserve_item דורש אישור וזהות משתמש. עצרו אחרי מספר צעדים מוגדר ובדקו חזרה מכשל בלי יצירת הזמנה כפולה.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','אפשר להתחיל ב־C# עם DTO, HttpClient, פונקציית כלי ו־CancellationToken. הרשאות נאכפות בשירות העסקי.','לפעולה אחת עשויה להספיק קריאת מודל ישירה. MCP מחבר כלים; A2A מחבר סוכנים; Temporal מנהל תהליך עמיד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agent-systems-fundamentals',0,'תפקיד וזרימת עבודה','workflow קבוע קובע את סדר הפעולות בקוד; סוכן יכול לבחור את הצעד הבא לפי מודל. הגדירו state, תקרת צעדים, timeout ו־cancellation. checkpoint שומר התקדמות אך אינו מבטיח שפעולה עסקית לא תוכפל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agent-systems-fundamentals',1,'מיקום במסלול הלמידה','מסלול מרכזי: לולאה ידנית קטנה לפני framework, ורק אחר כך מצב מתמשך או handoff לפי צורך.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agent-systems-fundamentals',2,'שילוב ב־C#/.NET','אפשר להתחיל ב־C# עם DTO, HttpClient, פונקציית כלי ו־CancellationToken. הרשאות נאכפות בשירות העסקי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agent-systems-fundamentals',3,'יתרונות ומתי לבחור','עקרונות ניידים בין SDKs מאפשרים בדיקות פשוטות והשוואה עניינית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agent-systems-fundamentals',4,'מגבלות, רישוי ונתונים','ריבוי סוכנים מוסיף תיאום ועלות; validation אינו הרשאה ו־retry אינו idempotency.');
insert into academy.entry_sections (entry_id,position,title,body) values ('agent-systems-fundamentals',5,'השוואה לחלופות','לפעולה אחת עשויה להספיק קריאת מודל ישירה. MCP מחבר כלים; A2A מחבר סוכנים; Temporal מנהל תהליך עמיד.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('agent-systems-fundamentals','must_learn','חובה להבין את לולאת הביצוע והאחריות לפני שימוש בהפשטות.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('agent-systems-fundamentals','לולאת מודל וכלים, מצב, תנאי עצירה, אישור אדם והתאוששות לפני בחירת מסגרת סוכנים.','אפשר להתחיל ב־C# עם DTO, HttpClient, פונקציית כלי ו־CancellationToken. הרשאות נאכפות בשירות העסקי.','not_applicable','פרק מושגי ללא מאגר מוצר.','2026-11-03');
insert into academy.entry_language_labels (entry_id,position,label) values ('agent-systems-fundamentals',0,'ידע מושגי — כל שפה');
