insert into academy.entry_sources(entry_id,position,source_url,title,checked_at,supports) select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://learn.microsoft.com/en-us/agent-framework/overview/','Microsoft Agent Framework overview','2026-11-03','Official overview has C# and Python examples and Go public preview, with missing Go-specific features; no claim of parity for every component.' from academy.entries e where e.slug='agent-systems-fundamentals' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://learn.microsoft.com/en-us/agent-framework/overview/');
