insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('microsoft-extensions-ai','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: עטפו IChatClient בשירות ASP.NET שמחזיר DTO ומפעיל get_stock מאומת; החליפו לקוח ובדקו תוצאה, cancellation ומגבלת כלים.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','SDK .NET רשמי. חבילת Microsoft.Extensions.AI נפרדת מ־Microsoft.Agents.AI; יכולות provider וגרסאות אינן זהות.','לקוח ספק ישיר מתאים לשימוש קטן; MAF מוסיפה סוכנים וזרימות. אין לייחס Stars של dotnet/extensions לחבילה בודדת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-extensions-ai',0,'תפקיד וזרימת עבודה','IChatClient ו־IEmbeddingGenerator מפרידים את קוד היישום מפרטי לקוח מסוים. הרחבות pipeline אינן מנוע תזמור מלא; IImageGenerator מתועד כ־Experimental בנפרד מההפשטות האחרות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-extensions-ai',1,'מיקום במסלול הלמידה','גשר מרכזי למפתח .NET לפני framework מלא. תרגיל אחד מספיק כדי להבין abstraction והחלפת ספק.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-extensions-ai',2,'שילוב ב־C#/.NET','SDK .NET רשמי. חבילת Microsoft.Extensions.AI נפרדת מ־Microsoft.Agents.AI; יכולות provider וגרסאות אינן זהות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-extensions-ai',3,'יתרונות ומתי לבחור','ממשקים מוכרים מאפשרים בדיקות והפרדת ספק בלי מסגרת סוכנים מלאה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-extensions-ai',4,'מגבלות, רישוי ונתונים','הפשטה אינה אחסון state או הרשאה עסקית. רכיבים Experimental מחייבים בדיקת חבילה; תנאי ספקי המודל נפרדים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-extensions-ai',5,'השוואה לחלופות','לקוח ספק ישיר מתאים לשימוש קטן; MAF מוסיפה סוכנים וזרימות. אין לייחס Stars של dotnet/extensions לחבילה בודדת.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('microsoft-extensions-ai','should_know','כדאי להכיר שכבה קטנה המשתלבת ב־DI ובקוד .NET קיים.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('microsoft-extensions-ai','ספריות .NET להפשטת קריאות מודל ו־embeddings וצינור logging, caching והפעלת כלים.','SDK .NET רשמי. חבילת Microsoft.Extensions.AI נפרדת מ־Microsoft.Agents.AI; יכולות provider וגרסאות אינן זהות.','not_applicable','אין מאגר מוצר ציבורי מייצג שנבחר; אין ייחוס Stars של SDK לכל השירות.','2026-11-03');
