insert into academy.entry_categories (entry_id,category_id,position) values ('strands-agents','02',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('strands-agents','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: שירות Python או TypeScript מחזיר הצעת טיפול לקריאה בלבד ל־ASP.NET; בדקו תקרת צעדים, כשל ספק ו־cancellation.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','Python ו־TypeScript; SDK C# מקומי לא אומת. ASP.NET יכול לצרוך שירות שתוכנן לכך, לא את הספרייה ישירות.','השוו ל־OpenAI Agents SDK או MAF באותו תרחיש, בלי להוסיף שני runtimes לאותה משימה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('strands-agents',0,'תפקיד וזרימת עבודה','זהות המאגר הקנונית היא harness-sdk; sdk-python הוא alias היסטורי ולא כלי שני. אין control plane מנוהל חובה; בחירת provider אינה מוגבלת מעצם השם לשירות Bedrock.');
insert into academy.entry_sections (entry_id,position,title,body) values ('strands-agents',1,'מיקום במסלול הלמידה','אופציונלי — להשוואה, העשרה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי ואין חובה לתרגל אותו. השוואת SDK במסלול Python/TypeScript; אינו צעד חובה נוסף במסלול .NET.');
insert into academy.entry_sections (entry_id,position,title,body) values ('strands-agents',2,'שילוב ב־C#/.NET','Python ו־TypeScript; SDK C# מקומי לא אומת. ASP.NET יכול לצרוך שירות שתוכנן לכך, לא את הספרייה ישירות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('strands-agents',3,'יתרונות ומתי לבחור','אפשר לשלב לולאה בתוך היישום ולהגדיר ספק וכלים לפי צורך.');
insert into academy.entry_sections (entry_id,position,title,body) values ('strands-agents',4,'מגבלות, רישוי ונתונים','Apache 2.0 לקוד נפרד מתנאי מודלים וענן; לקהל .NET נדרשת הצדקה ל־stack נוסף.');
insert into academy.entry_sections (entry_id,position,title,body) values ('strands-agents',5,'השוואה לחלופות','השוו ל־OpenAI Agents SDK או MAF באותו תרחיש, בלי להוסיף שני runtimes לאותה משימה.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('strands-agents','enrichment','העשרה להשוואת loop וספקים בתוך process. אופציונלי להשוואה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('strands-agents','SDK לסוכנים הפועלים בתוך תהליך היישום, עם ספקי מודלים, כלים ובקרת מחזור הרצה.','Python ו־TypeScript; SDK C# מקומי לא אומת. ASP.NET יכול לצרוך שירות שתוכנן לכך, לא את הספרייה ישירות.','unverified','זהות המאגר לפי המקור הרשמי; מדידה חסרה אינה אפס. אין head/latest מאומת מהמחקר.','2026-11-03');
