insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('deep-agents','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: מחקר בקבצים סינתטיים בתיקייה מוגבלת עם תת־סוכן אחד; השרת מאמת תוצר JSON והרשאות לפני שמירת מסקנות.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','Python ו־TypeScript; אין SDK C# מקומי מאומת או הבטחת parity לכל תכונה כגון profiles.','LangChain או LangGraph קטן עשויים להספיק. אין חובת שכבה שלישית מעל כל גרף.');
insert into academy.entry_sections (entry_id,position,title,body) values ('deep-agents',0,'תפקיד וזרימת עבודה','SDK, CLI ושירות Managed הם מסלולים נפרדים. הרשאות filesystem אינן חלות אוטומטית על כל shell של sandbox backend; יש לבדוק כל executor.');
insert into academy.entry_sections (entry_id,position,title,body) values ('deep-agents',1,'מיקום במסלול הלמידה','אופציונלי — להשוואה, העשרה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי ואין חובה לתרגל אותו. התמחות במשימות ארוכות עם קבצים והקשר, אחרי הבנת לולאה וגרף קטן.');
insert into academy.entry_sections (entry_id,position,title,body) values ('deep-agents',2,'שילוב ב־C#/.NET','Python ו־TypeScript; אין SDK C# מקומי מאומת או הבטחת parity לכל תכונה כגון profiles.');
insert into academy.entry_sections (entry_id,position,title,body) values ('deep-agents',3,'יתרונות ומתי לבחור','רכיבי תכנון והקשר מוכנים עשויים לחסוך תשתית חוזרת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('deep-agents',4,'מגבלות, רישוי ונתונים','MIT של SDK אינו תנאי השירות המנוהל. גישה לקבצים, shell ותתי־סוכנים מגדילה מורכבות והרשאות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('deep-agents',5,'השוואה לחלופות','LangChain או LangGraph קטן עשויים להספיק. אין חובת שכבה שלישית מעל כל גרף.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('deep-agents','enrichment','העשרה להבנת תפקיד harness כשניהול הקשר הופך לבעיה ממשית. אופציונלי להשוואה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('deep-agents','שכבת הרצה לסוכנים עם תכנון, קבצים, הקשר ותתי־סוכנים מעל LangChain ו־LangGraph.','Python ו־TypeScript; אין SDK C# מקומי מאומת או הבטחת parity לכל תכונה כגון profiles.','unverified','זהות המאגר לפי המקור הרשמי; מדידה חסרה אינה אפס. אין head/latest מאומת מהמחקר.','2026-11-03');
