insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('a2a','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: סוכן רכש פונה לסוכן מלאי בשירות נפרד; בדקו זהות, skill, מצב task, timeout והפרדת ארגונים.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','רשימת SDKs הרשמית מקשרת ל־a2aproject/a2a-dotnet. תמיכת C# רשמית אינה הבטחת שוויון גרסאות ויכולות לכל binding.','MCP מחבר סוכן לכלי; REST או פונקציה מקומית מספיקים לעיתים. אין לשכפל רשומת MCP בקטגוריה זו.');
insert into academy.entry_sections (entry_id,position,title,body) values ('a2a',0,'תפקיד וזרימת עבודה','AgentCard מתאר יכולות; הודעות ו־tasks מתאמים עבודה מעבר לגבול שירות. discovery אינו מעניק אמון, הרשאה או בידוד בין tenants.');
insert into academy.entry_sections (entry_id,position,title,body) values ('a2a',1,'מיקום במסלול הלמידה','אופציונלי — להשוואה, העשרה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי ואין חובה לתרגל אותו. התמחות interoperability כשיש סוכנים בשירותים נפרדים; אינו תנאי לבניית סוכן ראשון.');
insert into academy.entry_sections (entry_id,position,title,body) values ('a2a',2,'שילוב ב־C#/.NET','רשימת SDKs הרשמית מקשרת ל־a2aproject/a2a-dotnet. תמיכת C# רשמית אינה הבטחת שוויון גרסאות ויכולות לכל binding.');
insert into academy.entry_sections (entry_id,position,title,body) values ('a2a',3,'יתרונות ומתי לבחור','חוזה משותף מאפשר לבחון אינטגרציה בין צוותים ושירותים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('a2a',4,'מגבלות, רישוי ונתונים','Apache 2.0 למפרט אינו פוטר מבדיקת SDK, auth וגרסת פרוטוקול. בתהליך יחיד זו עשויה להיות שכבה מיותרת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('a2a',5,'השוואה לחלופות','MCP מחבר סוכן לכלי; REST או פונקציה מקומית מספיקים לעיתים. אין לשכפל רשומת MCP בקטגוריה זו.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('a2a','should_know','כדאי להכיר גבול agent-to-agent ולהבחין אותו מחיבור כלי. אופציונלי להשוואה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('a2a','פרוטוקול לגילוי סוכנים ולהחלפת הודעות ומשימות בין שירותים נפרדים.','רשימת SDKs הרשמית מקשרת ל־a2aproject/a2a-dotnet. תמיכת C# רשמית אינה הבטחת שוויון גרסאות ויכולות לכל binding.','unverified','מאגר המפרט של A2A; אינו מדד אימוץ SDK C# או מספר סוכנים פעילים.','2026-11-03');
