insert into academy.entry_categories (entry_id,category_id,position) values ('workflow-automation-fundamentals','03',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('workflow-automation-fundamentals','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: webhook לבקשת ציוד מגיע פעמיים; כשל מתרחש אחרי שמירה ולפני ACK. בדקו שהמזהה העסקי מונע הזמנה כפולה ושאישור מנהל נשמר.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','אפשר לתרגל ב־ASP.NET, SQL ו־Worker. חוזה JSON והרשאה נשארים באחריות השירות.','REST ו־Worker עשויים להספיק. n8n מחבר שירותים; Temporal מתאים לתהליך עמיד בקוד; Windmill ממוקד scripts.');
insert into academy.entry_sections (entry_id,position,title,body) values ('workflow-automation-fundamentals',0,'תפקיד וזרימת עבודה','webhook ו־polling הם מנגנוני קלט; timeout אינו הוכחה שפעולה לא בוצעה. תכננו מזהה עסקי, backoff, compensation ויומן. מודל הוא שלב אופציונלי ואינו מנוע הרשאות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('workflow-automation-fundamentals',1,'מיקום במסלול הלמידה','מסלול מרכזי: אירוע אחד ושירות קטן, אחריהם כלי אינטגרציה אחד. עמידות ארוכת טווח נלמדת לפי צורך.');
insert into academy.entry_sections (entry_id,position,title,body) values ('workflow-automation-fundamentals',2,'שילוב ב־C#/.NET','אפשר לתרגל ב־ASP.NET, SQL ו־Worker. חוזה JSON והרשאה נשארים באחריות השירות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('workflow-automation-fundamentals',3,'יתרונות ומתי לבחור','עקרונות ניידים מפחיתים תלות בכלי ובונים יכולת אבחון.');
insert into academy.entry_sections (entry_id,position,title,body) values ('workflow-automation-fundamentals',4,'מגבלות, רישוי ונתונים','תור או replay אינם בדיוק־פעם מול שירות חיצוני. רישוי, נתונים וסודות תלויים בפלטפורמה שנבחרה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('workflow-automation-fundamentals',5,'השוואה לחלופות','REST ו־Worker עשויים להספיק. n8n מחבר שירותים; Temporal מתאים לתהליך עמיד בקוד; Windmill ממוקד scripts.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('workflow-automation-fundamentals','must_learn','חובה להבין כשל וכפילויות בלי תלות בעורך חזותי מסוים.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('workflow-automation-fundamentals','טריגרים, חוזי אירועים, retries, מניעת כפילויות ואישור אדם לפני בחירת כלי אוטומציה.','אפשר לתרגל ב־ASP.NET, SQL ו־Worker. חוזה JSON והרשאה נשארים באחריות השירות.','not_applicable','פרק מושגי ללא מאגר מוצר.','2026-11-03');
