insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('make','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: ASP.NET שולח בקשה ל־scenario שמכין טיוטה וממתין לאישור; בדקו שתי בקשות במקביל וכשל חוזר.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','C# משתלב דרך HTTP או webhook. אין SDK C# מקומי או runner C# מאומת.','n8n ו־Activepieces מאפשרים בחינת אירוח עצמי; קוד Worker יכול להספיק לזרימה קטנה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('make',0,'תפקיד וזרימת עבודה','ב־instant webhooks עיבוד מקביל הוא ברירת המחדל המתועדת; עיבוד לפי סדר הוא בחירה מפורשת. גם סדר אינו מניעת כפילות. Make Code מתעד JavaScript ו־Python לפי מסלול.');
insert into academy.entry_sections (entry_id,position,title,body) values ('make',1,'מיקום במסלול הלמידה','אופציונלי — להשוואה, העשרה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי ואין חובה לתרגל אותו. השוואת SaaS מול n8n בלי ניהול שרת; תרגול נוסף רק כשיש צורך.');
insert into academy.entry_sections (entry_id,position,title,body) values ('make',2,'שילוב ב־C#/.NET','C# משתלב דרך HTTP או webhook. אין SDK C# מקומי או runner C# מאומת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('make',3,'יתרונות ומתי לבחור','חיבור חזותי מנוהל מצמצם עבודת תפעול ראשונית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('make',4,'מגבלות, רישוי ונתונים','SaaS מסחרי עם מכסות ונתונים בתור; Code במסלולים בתשלום אינו היתר בלתי מוגבל להרצת קוד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('make',5,'השוואה לחלופות','n8n ו־Activepieces מאפשרים בחינת אירוח עצמי; קוד Worker יכול להספיק לזרימה קטנה.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('make','should_know','כדאי להכיר חלופה מנוהלת וללמוד משמעות של concurrency ומכסות. אופציונלי להשוואה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('make','שירות אוטומציה חזותי להרכבת scenarios, טריגרים, webhooks וקריאות HTTP.','C# משתלב דרך HTTP או webhook. אין SDK C# מקומי או runner C# מאומת.','not_applicable','אין מאגר מוצר ציבורי מייצג שנבחר; אין ייחוס Stars של SDK לכל השירות.','2026-11-03');
