insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('zapier','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: Zap מסנכרן אישור ממערכת צד שלישי ל־ASP.NET; ה־API מאמת משתמש ומפתח idempotency.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','Code מתעד JavaScript ו־Python; אין runner C# מאומת. שירות .NET משתלב באמצעות API.','Make ו־n8n חלופות לפי אירוח ו־connectors; Composio ב־09 ממוקד חיבור כלים לסוכן.');
insert into academy.entry_sections (entry_id,position,title,body) values ('zapier',0,'תפקיד וזרימת עבודה','connections ופעולות מחברות שירותים לתהליך. המעבר מ־Functions ל־Code הוא שינוי רכיב ואינו הפסקת Zapier.');
insert into academy.entry_sections (entry_id,position,title,body) values ('zapier',1,'מיקום במסלול הלמידה','אופציונלי — להשוואה, העשרה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי ואין חובה לתרגל אותו. חלופה להשוואת connectors ושירות מנוהל, בלי חובת תרגיל נוסף.');
insert into academy.entry_sections (entry_id,position,title,body) values ('zapier',2,'שילוב ב־C#/.NET','Code מתעד JavaScript ו־Python; אין runner C# מאומת. שירות .NET משתלב באמצעות API.');
insert into academy.entry_sections (entry_id,position,title,body) values ('zapier',3,'יתרונות ומתי לבחור','אינטגרציות מנוהלות עשויות לצמצם קוד חיבור בין שירותים קיימים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('zapier',4,'מגבלות, רישוי ונתונים','שירות מסחרי; runtime limits, הרשאות connections ועלות מחייבים בדיקת מסלול. SDK JavaScript אינו SDK .NET.');
insert into academy.entry_sections (entry_id,position,title,body) values ('zapier',5,'השוואה לחלופות','Make ו־n8n חלופות לפי אירוח ו־connectors; Composio ב־09 ממוקד חיבור כלים לסוכן.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('zapier','should_know','כדאי להכיר מערכת אינטגרציות מנוהלת ואת גבולות החיבור לשירות העסקי. אופציונלי להשוואה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי.','2026-11-03','editorial_learning');
