insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('activepieces','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: תכננו flow מול API מחסן .NET ובדקו סודות, retry ומידע הנשמר בכל execution לפני בחירת תצורת אירוח.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','פיתוח pieces ב־TypeScript; שירות C# צורך API/webhooks. SDK .NET מקומי לא אומת.','n8n שונה ברישוי; Make חוסך ניהול שרת; שירות קטן יכול להספיק.');
insert into academy.entry_sections (entry_id,position,title,body) values ('activepieces',0,'תפקיד וזרימת עבודה','הליבה ברישיון MIT לצד מהדורות מסחריות; בחירת hosting נפרדת מזכאות לתכונות Enterprise.');
insert into academy.entry_sections (entry_id,position,title,body) values ('activepieces',1,'מיקום במסלול הלמידה','אופציונלי — להשוואה, העשרה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי ואין חובה לתרגל אותו. השוואת רישוי ואירוח מול n8n; אינו כלי חובה נוסף.');
insert into academy.entry_sections (entry_id,position,title,body) values ('activepieces',2,'שילוב ב־C#/.NET','פיתוח pieces ב־TypeScript; שירות C# צורך API/webhooks. SDK .NET מקומי לא אומת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('activepieces',3,'יתרונות ומתי לבחור','בחירה בין ענן לאירוח עצמי וליבת MIT מאפשרת השוואת שליטה ותפעול.');
insert into academy.entry_sections (entry_id,position,title,body) values ('activepieces',4,'מגבלות, רישוי ונתונים','Enterprise וענן אינם הבטחה לתכונות חינם. אירוח עצמי אינו מונע egress כאשר piece פונה ל־SaaS.');
