insert into academy.entry_categories (entry_id,category_id,position) values ('windmill','03',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('windmill','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: C# script קורא נתוני מחסן ומפיק טיוטת רכש; חברו שלב אישור והפרידו סודות מקלט ויומן.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','מדריך C# רשמי מתעד static Main ותלויות. מודל scripts אינו זהה ל־SDK .NET של Temporal ול־replay שלו.','n8n לחיבור חזותי, Temporal לעמידות בקוד ו־Worker קטן לזרימה פשוטה. אין צורך לתרגל את שלושתם.');
insert into academy.entry_sections (entry_id,position,title,body) values ('windmill',0,'תפקיד וזרימת עבודה','script עם נקודת כניסה וגרסה הופך לצעד בזרימה. תמיכת C# היא הרצת script בפועל ולא רק קריאת HTTP; יש לבדוק dependencies ו־worker.');
insert into academy.entry_sections (entry_id,position,title,body) values ('windmill',1,'מיקום במסלול הלמידה','מסלול קוד לבחירה כשיש ערך בשימוש ב־C# scripts. אינו חובת תרגול לצד n8n או Temporal.');
insert into academy.entry_sections (entry_id,position,title,body) values ('windmill',2,'שילוב ב־C#/.NET','מדריך C# רשמי מתעד static Main ותלויות. מודל scripts אינו זהה ל־SDK .NET של Temporal ול־replay שלו.');
insert into academy.entry_sections (entry_id,position,title,body) values ('windmill',3,'יתרונות ומתי לבחור','אפשר למחזר ידע C# בתוך אוטומציה עם גרסאות scripts.');
insert into academy.entry_sections (entry_id,position,title,body) values ('windmill',4,'מגבלות, רישוי ונתונים','AGPL 3 לליבה עם חריגים וקוד Enterprise מסחרי; רישיון clients/OpenAPI נפרד. workers, timeout ו־cache דורשים תכנון.');
insert into academy.entry_sections (entry_id,position,title,body) values ('windmill',5,'השוואה לחלופות','n8n לחיבור חזותי, Temporal לעמידות בקוד ו־Worker קטן לזרימה פשוטה. אין צורך לתרגל את שלושתם.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('windmill','should_know','כדאי להכיר נתיב אוטומציה ממוקד קוד שמתאים לידע .NET.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('windmill','פלטפורמה להרכבת scripts ל־flows ויישומים, עם מסלול C# רשמי.','מדריך C# רשמי מתעד static Main ותלויות. מודל scripts אינו זהה ל־SDK .NET של Temporal ול־replay שלו.','unverified','זהות המאגר לפי המקור הרשמי; מדידה חסרה אינה אפס. אין head/latest מאומת מהמחקר.','2026-11-03');
