insert into academy.entry_categories (entry_id,category_id,position) values ('power-automate','03',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('power-automate','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: cloud flow מאשר רכש דרך connector; רק מערכת שאין לה API מקבלת שלב desktop, עם בדיקות כשל ושינוי UI.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','custom connector תומך בקוד C# לטרנספורמציית request/response תחת מגבלות .NET Standard 2.0 ו־namespaces. אין זה SDK תזמור .NET כללי.','API ישיר עמיד לרוב יותר מ־UI משתנה; n8n או Make להשוואת cloud flow, ו־Copilot Studio לבניית עוזר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('power-automate',0,'תפקיד וזרימת עבודה','cloud flow מחבר שירותים; desktop flow מפעיל RPA. אלה מסלולים שונים, ו־Copilot Studio הוא מוצר נפרד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('power-automate',1,'מיקום במסלול הלמידה','אופציונלי — להשוואה, העשרה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי ואין חובה לתרגל אותו. התמחות בארגון Microsoft או ב־RPA למערכת ללא API; אינה דרישת יסוד לכל workflow.');
insert into academy.entry_sections (entry_id,position,title,body) values ('power-automate',2,'שילוב ב־C#/.NET','custom connector תומך בקוד C# לטרנספורמציית request/response תחת מגבלות .NET Standard 2.0 ו־namespaces. אין זה SDK תזמור .NET כללי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('power-automate',3,'יתרונות ומתי לבחור','עשוי להתאים לתהליכים ולזהויות קיימים בסביבת Microsoft.');
insert into academy.entry_sections (entry_id,position,title,body) values ('power-automate',4,'מגבלות, רישוי ונתונים','מוצר מסחרי; רישיונות connectors ו־attended/unattended תלויים מסלול. תיעוד timeout סותר בין דפים ולכן אין כאן מספר אחיד מובטח.');
insert into academy.entry_sections (entry_id,position,title,body) values ('power-automate',5,'השוואה לחלופות','API ישיר עמיד לרוב יותר מ־UI משתנה; n8n או Make להשוואת cloud flow, ו־Copilot Studio לבניית עוזר.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('power-automate','should_know','כדאי להכיר חלופה ארגונית תוך הבנת ההבדל בין API לאוטומציית UI. אופציונלי להשוואה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('power-automate','תהליכי ענן ואוטומציית שולחן עבודה בארגון Microsoft, עם connectors.','custom connector תומך בקוד C# לטרנספורמציית request/response תחת מגבלות .NET Standard 2.0 ו־namespaces. אין זה SDK תזמור .NET כללי.','not_applicable','אין מאגר מוצר ציבורי מייצג שנבחר; אין ייחוס Stars של SDK לכל השירות.','2026-11-03');
