insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('training-mlops-fundamentals','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: סווגו בקשות ציוד סינתטיות, חלקו לפי זמן ומשתמש, והשוו כלל עסקי ומודל קיים לפני שינוי משקלים.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','אימון Python יכול להפיק artifact או endpoint שנצרך מ־.NET. אימון והסקה הם שלבים נפרדים.','rules, prompt או RAG עשויים להספיק; inference ב־08 והערכה ב־10 משלימים את המחזור.');
insert into academy.entry_sections (entry_id,position,title,body) values ('training-mlops-fundamentals',0,'תפקיד וזרימת עבודה','prompt משנה קלט; fine-tuning משנה פרמטרים. הפרידו train/validation/test לפני עיבוד שלומד סטטיסטיקה, בדקו leakage ותעדו מקור ורישיון. ניסוי כולל data version, config, metrics ו־artifact.');
insert into academy.entry_sections (entry_id,position,title,body) values ('training-mlops-fundamentals',1,'מיקום במסלול הלמידה','חובה להבין את ההחלטה; אין חובה לאמן מודל לפני פיתוח API. מתחילים ב־baseline וב־held-out eval.');
insert into academy.entry_sections (entry_id,position,title,body) values ('training-mlops-fundamentals',2,'שילוב ב־C#/.NET','אימון Python יכול להפיק artifact או endpoint שנצרך מ־.NET. אימון והסקה הם שלבים נפרדים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('training-mlops-fundamentals',3,'יתרונות ומתי לבחור','מדד ובסיס השוואה מאפשרים החלטת התאמה עניינית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('training-mlops-fundamentals',4,'מגבלות, רישוי ונתונים','מדגם קטן אינו הוכחת הכללה. רישיון ספרייה אינו רישיון dataset או checkpoint; GPU ונתוני משתמשים דורשים תכנון.');
insert into academy.entry_sections (entry_id,position,title,body) values ('training-mlops-fundamentals',5,'השוואה לחלופות','rules, prompt או RAG עשויים להספיק; inference ב־08 והערכה ב־10 משלימים את המחזור.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('training-mlops-fundamentals','must_learn','יסודות נתונים והערכה מונעים אימון מיותר ומסקנות ממדגם לא מייצג.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('training-mlops-fundamentals','החלטה מתי להתאים מודל, הפרדת נתונים, מעקב ניסויים ותוצר בר־שחזור לפני אימון.','אימון Python יכול להפיק artifact או endpoint שנצרך מ־.NET. אימון והסקה הם שלבים נפרדים.','not_applicable','פרק מושגי ללא מאגר מוצר.','2026-11-03');
