insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('hf-transformers','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: התאימו checkpoint מורשה לסיווג פניות; שמרו tokenizer, config וגרסה, והעריכו לפני חיבור endpoint ל־ASP.NET.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','מסלול Python לאימון; .NET צורך שירות או artifact עם runtime מתאים. אין SDK C# מקומי מקביל לכל Trainer.','API מנוהל או prompt עשויים להספיק; PyTorch היא שכבת יסוד, ו־PEFT מצמצמת פרמטרים לאימון במקרים מתאימים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-transformers',0,'תפקיד וזרימת עבודה','workflow טיפוסי בוחר checkpoint, tokenizer ונתונים, מגדיר אימון ומעריך על holdout. Trainer שנבדק מתאר מסלול PyTorch; אין כאן העתקת מטריצת backends ממדריך ישן.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-transformers',1,'מיקום במסלול הלמידה','נתיב מרכזי אפשרי רק כשנדרשת התאמה; קראו Model Card ותעדו baseline תחילה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-transformers',2,'שילוב ב־C#/.NET','מסלול Python לאימון; .NET צורך שירות או artifact עם runtime מתאים. אין SDK C# מקומי מקביל לכל Trainer.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-transformers',3,'יתרונות ומתי לבחור','ממשקים למודלים מוכנים מפחיתים צורך במימוש ארכיטקטורה מאפס.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-transformers',4,'מגבלות, רישוי ונתונים','Apache 2.0 לקוד אינו רישיון כל משקלי המודלים. חומרה, זיכרון, גרסאות ויכולת export דורשים בדיקה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-transformers',5,'השוואה לחלופות','API מנוהל או prompt עשויים להספיק; PyTorch היא שכבת יסוד, ו־PEFT מצמצמת פרמטרים לאימון במקרים מתאימים.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('hf-transformers','should_know','כדאי להכיר שכבת שימוש והתאמה למודלים מוכנים, בנפרד מה־Hub והספקים.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('hf-transformers','ספרייה להגדרות מודלים, שימוש ב־checkpoints מוכנים והתאמה למשימה עם כלים כגון Trainer.','מסלול Python לאימון; .NET צורך שירות או artifact עם runtime מתאים. אין SDK C# מקומי מקביל לכל Trainer.','verified','זהות המאגר לפי המקור הרשמי; מדידה חסרה אינה אפס. אין head/latest מאומת מהמחקר.','2026-11-03');
