insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('hf-datasets','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: צרו dataset סינתטי עם provenance, הסירו כפילויות וחלקו לפי משתמש וזמן; בדקו שאין נתון test בתוך train.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','Python; .NET יכול להכין נתונים או לצרוך תוצאות דרך תהליך מוסכם. אין API C# מקומי מאומת של הספרייה.','CSV/SQL ותהליך קטן עשויים להספיק. Hub הוא מקום לשיתוף, ו־Datasets היא ספריית עבודה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-datasets',0,'תפקיד וזרימת עבודה','הספרייה מנהלת גישה וטרנספורמציות לנתונים; היא אינה מעניקה רישיון לתוכן. תעדו מקור, גרסה, חלוקה והסרת כפילויות לפני preprocessing שנלמד מהנתונים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-datasets',1,'מיקום במסלול הלמידה','נתונים והפרדת holdout קודמים ל־tuning; אפשר להתחיל גם ב־CSV או SQL קטן.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-datasets',2,'שילוב ב־C#/.NET','Python; .NET יכול להכין נתונים או לצרוך תוצאות דרך תהליך מוסכם. אין API C# מקומי מאומת של הספרייה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-datasets',3,'יתרונות ומתי לבחור','כלים אחידים לטעינה ועיבוד מסייעים לחזור על ניסוי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-datasets',4,'מגבלות, רישוי ונתונים','Apache 2.0 לספרייה נפרד מרישיון dataset. PII ו־leakage אינם נפתרים אוטומטית; streaming אינו מבטל ניהול גרסה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-datasets',5,'השוואה לחלופות','CSV/SQL ותהליך קטן עשויים להספיק. Hub הוא מקום לשיתוף, ו־Datasets היא ספריית עבודה.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('hf-datasets','should_know','כדאי להכיר reproducibility ואיכות נתונים לפני בחירת אלגוריתם.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('hf-datasets','ספרייה לטעינה, עיבוד וזרימה של נתונים לניסויי ML ואימון.','Python; .NET יכול להכין נתונים או לצרוך תוצאות דרך תהליך מוסכם. אין API C# מקומי מאומת של הספרייה.','verified','זהות המאגר לפי המקור הרשמי; מדידה חסרה אינה אפס. אין head/latest מאומת מהמחקר.','2026-11-03');
