insert into academy.entry_categories (entry_id,category_id,position) values ('hf-peft','11',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('hf-peft','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: השוו LoRA ל־checkpoint מורשה מול בסיס ללא התאמה באותו holdout; שמרו גרסאות ובדקו טעינה בנתיב ההסקה המתוכנן.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','Python; טעינת adapter ב־runtime שמשמש .NET דורשת בדיקת תאימות נפרדת.','prompt/RAG, התאמה מלאה או API מנוהל הן חלופות לפי מדידה. TRL מוסיפה אלגוריתמי post-training, לא תחליף לרישוי נתונים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-peft',0,'תפקיד וזרימת עבודה','adapter מתאים חלק מהפרמטרים או מוסיף רכיבים קטנים לצד מודל בסיס. יש לתעד בסיס, שיטת התאמה, config וגרסת adapter יחד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-peft',1,'מיקום במסלול הלמידה','שלב מותנה אחרי baseline ו־dataset תקין; אין הבטחת צורך ב־LoRA לכל יישום.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-peft',2,'שילוב ב־C#/.NET','Python; טעינת adapter ב־runtime שמשמש .NET דורשת בדיקת תאימות נפרדת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-peft',3,'יתרונות ומתי לבחור','עשויה לצמצם פרמטרים משתנים ואחסון ביחס להתאמה מלאה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-peft',4,'מגבלות, רישוי ונתונים','אין הבטחת חיסכון מספרית או איכות משופרת. Apache 2.0 לקוד אינו רישיון משקלי הבסיס או הנתונים; adapter אינו תואם לכל runtime.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-peft',5,'השוואה לחלופות','prompt/RAG, התאמה מלאה או API מנוהל הן חלופות לפי מדידה. TRL מוסיפה אלגוריתמי post-training, לא תחליף לרישוי נתונים.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('hf-peft','should_know','כדאי להכיר דרך נפוצה לבחינת התאמה בלי אימון מלא.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('hf-peft','ספרייה להתאמה חסכונית בפרמטרים, לרבות LoRA, במקום עדכון כל משקלי המודל.','Python; טעינת adapter ב־runtime שמשמש .NET דורשת בדיקת תאימות נפרדת.','verified','זהות המאגר לפי המקור הרשמי; מדידה חסרה אינה אפס. אין head/latest מאומת מהמחקר.','2026-11-03');
