insert into academy.entry_categories (entry_id,category_id,position) values ('hf-trl','11',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('hf-trl','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: תכננו SFT קטן עם labels ו־chat template, בדקו holdout ואז החליטו אם נתוני העדפות מצדיקים DPO.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','Python עם תלויות מודל וחומרה; SDK C# מקומי לא אומת.','Transformers Trainer או PEFT עשויים להספיק; אין צורך להפעיל כמה שיטות ללא שאלה מדידה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-trl',0,'תפקיד וזרימת עבודה','בחרו trainer לפי מטרה ונתונים; SFT, DPO ו־GRPO אינם אותו תהליך. chat template, labels ו־eval חייבים להתאים למשימה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-trl',1,'מיקום במסלול הלמידה','אופציונלי — להשוואה, העשרה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי ואין חובה לתרגל אותו. התמחות אחרי dataset, baseline והתאמה פשוטה; RL אינו תרגיל ראשון.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-trl',2,'שילוב ב־C#/.NET','Python עם תלויות מודל וחומרה; SDK C# מקומי לא אומת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-trl',3,'יתרונות ומתי לבחור','trainers ייעודיים מרכזים קוד אלגוריתמי ותצורה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-trl',4,'מגבלות, רישוי ונתונים','Apache 2.0 לקוד נפרד ממשקלים ונתונים. reward hacking ועלות דורשים eval. תיעוד usage stats מציין telemetry בעת יצירת trainer ואפשרויות opt-out/offline; אימון מקומי אינו הבטחת אפס תעבורה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('hf-trl',5,'השוואה לחלופות','Transformers Trainer או PEFT עשויים להספיק; אין צורך להפעיל כמה שיטות ללא שאלה מדידה.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('hf-trl','enrichment','העשרה חשובה כשנדרשת שיטת post-training מוגדרת, ולא עוד שלב חובה. אופציונלי להשוואה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('hf-trl','ספריית post-training עם trainers ל־SFT, אופטימיזציית העדפות ולמידת חיזוק.','Python עם תלויות מודל וחומרה; SDK C# מקומי לא אומת.','verified','זהות המאגר לפי המקור הרשמי; מדידה חסרה אינה אפס. אין head/latest מאומת מהמחקר.','2026-11-03');
