insert into academy.entry_categories (entry_id,category_id,position) values ('mlflow','11',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('mlflow','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: השוו שני runs עם seed, data hash, config, metric ו־artifact; קדמו alias רק לאחר סקירת eval ותוכנית rollback.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','אינדקס API רשמי כולל Python, TypeScript, R, Java ו־REST. לקוח C# רשמי לא אומת; HttpClient אינו SDK .NET של MLflow.','קובץ metadata מספיק לניסוי זעיר. Langfuse ממוקדת ביישומי LLM וב־traces; אין צורך בשני backends לתרגיל ראשון.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mlflow',0,'תפקיד וזרימת עבודה','run מקשר config, נתונים ותוצאות; Registry מוסיף versions ו־aliases. קידום alias אינו אישור לפריסה. יכולות GenAI חופפות לתצפיתיות ב־10, אך נשמרת רשומה אחת ב־11.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mlflow',1,'מיקום במסלול הלמידה','תעדו ניסוי אחד באופן עקיב; tracker אחד מספיק. אפשר להתחיל בקובץ metadata לפני שרת משותף.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mlflow',2,'שילוב ב־C#/.NET','אינדקס API רשמי כולל Python, TypeScript, R, Java ו־REST. לקוח C# רשמי לא אומת; HttpClient אינו SDK .NET של MLflow.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mlflow',3,'יתרונות ומתי לבחור','עקיבות מקלה להשוות ניסויים ולזהות מה הופעל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mlflow',4,'מגבלות, רישוי ונתונים','Apache 2.0 לקוד. Registry בשרת עצמאי דורש backend DB ותכנון אבטחת server/artifact store; הרשומה אינה הוראה להקים תשתית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('mlflow',5,'השוואה לחלופות','קובץ metadata מספיק לניסוי זעיר. Langfuse ממוקדת ביישומי LLM וב־traces; אין צורך בשני backends לתרגיל ראשון.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('mlflow','should_know','כדאי להכיר קשר בין ניסוי, artifact ומודל שנצרך בייצור.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('mlflow','מעקב ניסויים וניהול מודלים: פרמטרים, מדדים, artifacts וגרסאות לקראת הפעלה.','אינדקס API רשמי כולל Python, TypeScript, R, Java ו־REST. לקוח C# רשמי לא אומת; HttpClient אינו SDK .NET של MLflow.','verified','זהות המאגר לפי המקור הרשמי; מדידה חסרה אינה אפס. אין head/latest מאומת מהמחקר.','2026-11-03');
