insert into academy.entry_categories (entry_id,category_id,position) values ('torchsharp','11',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('torchsharp','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: בנו מסווג קטן ב־C#, שמרו וטענו תוצר ובדקו חזרתיות וניהול משאבים לפני הרחבה.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','API .NET אמיתי, עם אחריות לזיכרון native ותלויות. README מגביל מחשבי Intel Mac לקו 0.102.8; אין הבטחת parity לאקוסיסטם Python.','PyTorch Python מספק אקוסיסטם רחב יותר; ML.NET מתאימה למשימות ML קלאסיות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('torchsharp',0,'תפקיד וזרימת עבודה','הספרייה מגשרת ליכולות native של LibTorch. יש להתאים חבילת runtime, חומרה ומערכת הפעלה; README מזהיר משינויים שוברים בדרך ל־1.0.');
insert into academy.entry_sections (entry_id,position,title,body) values ('torchsharp',1,'מיקום במסלול הלמידה','אופציונלי — להשוואה, העשרה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי ואין חובה לתרגל אותו. התמחות ML ב־C# כשיש הצדקה; אינה תחליף אוטומטי למסלול Python ו־Hugging Face.');
insert into academy.entry_sections (entry_id,position,title,body) values ('torchsharp',2,'שילוב ב־C#/.NET','API .NET אמיתי, עם אחריות לזיכרון native ותלויות. README מגביל מחשבי Intel Mac לקו 0.102.8; אין הבטחת parity לאקוסיסטם Python.');
insert into academy.entry_sections (entry_id,position,title,body) values ('torchsharp',3,'יתרונות ומתי לבחור','אפשר לעבוד עם מושגי ML בשפה קיימת בלי מעבר Python לכל פעולה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('torchsharp',4,'מגבלות, רישוי ונתונים','MIT למעטפת; תלויות native ורישיונותיהן נבדקים בנפרד. קו pre-1.0 ושילוב חומרה מגבילים ניידות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('torchsharp',5,'השוואה לחלופות','PyTorch Python מספק אקוסיסטם רחב יותר; ML.NET מתאימה למשימות ML קלאסיות.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('torchsharp','enrichment','העשרה מעשית למפתחי .NET שרוצים להבין tensors ואימון בתוך C#. אופציונלי להשוואה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('torchsharp','מעטפת .NET ל־LibTorch לעבודה עם tensors ומודלים בקוד C#.','API .NET אמיתי, עם אחריות לזיכרון native ותלויות. README מגביל מחשבי Intel Mac לקו 0.102.8; אין הבטחת parity לאקוסיסטם Python.','verified','זהות המאגר לפי המקור הרשמי; מדידה חסרה אינה אפס. אין head/latest מאומת מהמחקר.','2026-11-03');
