insert into academy.entry_categories (entry_id,category_id,position) values ('ml-net','11',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('ml-net','ידע בפיתוח תוכנה, HTTP, בדיקות והרשאות; קראו את פרק היסודות של הקטגוריה לפני בחירת מוצר.','דוגמה מעשית מוצעת שלא הורצה: סווגו פניות או חזו ביקוש לציוד מנתונים סינתטיים, והשוו לכלל עסקי על holdout נפרד.','הגדירו תנאי קבלה לתרחיש, baseline וחלופה אחת. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; תעדו גרסאות ותוצאה לפני פעולה עסקית. התרגיל הוא הצעה ולא תוצאת ניסוי.','API .NET רשמי; ליבת Microsoft.ML מכוונת netstandard2, אך חבילות אופציונליות ותלויות חומרה משתנות.','TorchSharp מתאימה לעבודה מפורשת עם tensors; Transformers למסלול pretrained Python; כלל SQL עשוי להספיק.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ml-net',0,'תפקיד וזרימת עבודה','pipeline נתונים ואימון משתלב ביישום .NET. הספרייה אינה API כללי להתאמת כל LLM או חלופה מלאה ל־Transformers.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ml-net',1,'מיקום במסלול הלמידה','אופציונלי — להשוואה, העשרה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי ואין חובה לתרגל אותו. התמחות .NET לבעיה קלאסית; אין צורך ללמוד אותה לצד כל ספריית אימון.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ml-net',2,'שילוב ב־C#/.NET','API .NET רשמי; ליבת Microsoft.ML מכוונת netstandard2, אך חבילות אופציונליות ותלויות חומרה משתנות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ml-net',3,'יתרונות ומתי לבחור','אפשר להישאר ב־C# עבור משימות ML מתאימות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ml-net',4,'מגבלות, רישוי ונתונים','MIT לקוד עם הודעות צד שלישי. תמיכת צריכת ONNX או TensorFlow אינה אימון כל מודל ואינה הבטחת תמיכת LLM.');
insert into academy.entry_sections (entry_id,position,title,body) values ('ml-net',5,'השוואה לחלופות','TorchSharp מתאימה לעבודה מפורשת עם tensors; Transformers למסלול pretrained Python; כלל SQL עשוי להספיק.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('ml-net','enrichment','העשרה שמזכירה כי AI יישומי כולל גם ML קלאסי בתוך stack קיים. אופציונלי להשוואה או התמחות; אינו חלק אוטומטי מהמסלול המרכזי.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('ml-net','מסגרת ML ב־.NET לאימון ולצריכת מודלים במשימות כגון סיווג וחיזוי.','API .NET רשמי; ליבת Microsoft.ML מכוונת netstandard2, אך חבילות אופציונליות ותלויות חומרה משתנות.','unverified','זהות המאגר לפי המקור הרשמי; מדידה חסרה אינה אפס. אין head/latest מאומת מהמחקר.','2026-11-03');
