insert into academy.entry_language_labels (entry_id,position,label) values ('codex',0,'קוד פרויקט — לפי סביבת העבודה');
insert into academy.entry_sections (entry_id,position,title,body) values ('codex',5,'הרחבה מאומתת — תפקיד ומסלול','sandbox מגביל טכנית קבצים ורשת; approval קובע מתי נדרשת הרשאה לפעולה. מנגנונים משתנים לפי סביבת ההרצה. Codex לפיתוח קוד נבדל מ־Codex Security לסריקת מאגרים. מתחילים במשימה אחת ובסקירת diff.');
insert into academy.entry_sections (entry_id,position,title,body) values ('codex',6,'מגבלות ורישוי — עדכון','Apache 2.0 של CLI אינו רישיון השירות או המודל. אישור פקודה אינו הוכחת נכונות התוצר; מגבלות רשת פקודות אינן בהכרח מגבלות connectors או דפדפן.');
insert into academy.entry_sections (entry_id,position,title,body) values ('codex',7,'השוואה ובחירת מסלול','אין חובה בעוזר מסוים: Copilot מתאים לבחינת Visual Studio, Claude Code למסלול סוכני ו־Cursor להשוואת IDE. בחרו אחד לתרגיל המרכזי.');
