insert into academy.entry_language_labels (entry_id,position,label) values ('claude-code',0,'קוד פרויקט — לפי סביבת העבודה');
insert into academy.entry_sections (entry_id,position,title,body) values ('claude-code',5,'הרחבה מאומתת — תפקיד ומסלול','מצבי הרשאה ואישורים שמורים משפיעים על עריכה ופקודות. אישור Bash אינו בידוד מערכת הפעלה לפי working directory בלבד; sandbox הוא בקרה נוספת. הגדירו הקשר ותנאי קבלה לפני משימה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('claude-code',6,'מגבלות ורישוי — עדכון','מדיניות נתוני consumer תלויה בהגדרות, ומסלולים מסחריים כפופים למדיניות נפרדת. אין הבטחת no-training לכל חשבון, ורישיון מאגר תיעוד אינו רישיון כל המוצר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('claude-code',7,'השוואה ובחירת מסלול','חלופה מרכזית לעוזר הקיים, ללא חובת לימוד מוצר שני. השוו סקירת שינויים ובדיקות באותה משימה.');
