insert into academy.entry_language_labels (entry_id,position,label) values ('cursor',0,'קוד פרויקט — לפי סביבת העבודה');
insert into academy.entry_sections (entry_id,position,title,body) values ('cursor',5,'הרחבה מאומתת — תפקיד ומסלול','שינויים ב־workspace עשויים להישמר ישירות; auto-reload יכול להריץ קוד לפני סקירה. checkpoint הוא כלי נוחות ואינו מחליף Git או בדיקת diff.');
insert into academy.entry_sections (entry_id,position,title,body) values ('cursor',6,'מגבלות ורישוי — עדכון','Privacy Mode משפיע על שימוש לאימון, עם חריגי retention מתועדים. בקשות עם API key פרטי עדיין עשויות לעבור backend; אין הבטחת עיבוד מקומי בלבד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('cursor',7,'השוואה ובחירת מסלול','בחרו Cursor אם ממשק IDE תורם לתהליך. Devin Desktop הוא חלופה להשוואה; Codex או Claude Code מתאימים גם בלי מעבר עורך.');
