insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-agent-framework',5,'הרחבה מאומתת — תפקיד ומסלול','למדו לולאה קטנה או Extensions.AI לפני סוכן ו־workflow. הרשאה לכלי, שמירת state וטיפול ב־side effects נשארים החלטות יישום. גרסאות .NET ו־Python במאגר אינן אותו מספר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-agent-framework',6,'מגבלות ורישוי — עדכון','ליבת הקוד MIT; תנאי מודלים ושירותי ענן נפרדים. הסרת הערת prerelease כללית ל־.NET אינה טענת GA לכל רכיב או parity לכל שפה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-agent-framework',7,'השוואה ובחירת מסלול','MAF היא מסלול .NET מרכזי; LangGraph משמשת להשוואת state וגרף. אין צורך לבנות אותו תרגיל בכל framework.');
