insert into academy.entry_language_labels (entry_id,position,label) values ('langgraph',1,'JavaScript/TypeScript');
insert into academy.entry_sections (entry_id,position,title,body) values ('langgraph',5,'הרחבה מאומתת — תפקיד ומסלול','state, edges ו־checkpoints מציגים התקדמות מפורשת. durable execution אינו בדיוק־פעם של side effects חיצוניים; נדרש מפתח עסקי למניעת כפילות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langgraph',6,'מגבלות ורישוי — עדכון','MIT לליבה נפרד משירותי פריסה. בחירת persistence, replay וגרסאות דורשת בדיקה; גרף אינו מועיל אוטומטית לבקשת מודל אחת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langgraph',7,'השוואה ובחירת מסלול','חשוב להכיר מצב מפורש, אך אפשר לתרגל ב־MAF ב־.NET ולהשוות את התכנון בלבד. LangChain מוסיפה הרכבת loop ו־middleware.');
insert into academy.sources(url) values ('https://docs.langchain.com/oss/python/langgraph/overview') on conflict do nothing;
