insert into academy.entry_sections (entry_id,position,title,body) values ('langchain',5,'הרחבה מאומתת — תפקיד ומסלול','הבחינו LangChain להרכבת סוכן ו־middleware, LangGraph לניהול מצב והרצה, ו־Deep Agents לשכבת תכנון והקשר. אין צורך בשלוש השכבות לכל משימה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langchain',6,'מגבלות ורישוי — עדכון','MIT לקוד פתוח אינו תנאי LangSmith או שירותי deployment. החלפת provider אינה מבטיחה אותה התנהגות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langchain',7,'השוואה ובחירת מסלול','בחרו stack אחד: LangChain לאינטגרציות, OpenAI Agents SDK ללולאה בתוך יישום או MAF למסלול .NET. Deep Agents היא התמחות ולא prerequisite.');
