insert into academy.entry_sections (entry_id,position,title,body) values ('openai-agents-sdk',5,'הרחבה מאומתת — תפקיד ומסלול','SDK רץ ביישום ומנהל loop; Agents API מריץ שכבת הרצה מנוהלת בשירות, ו־Responses API הוא מסלול API נפרד. בחרו לפי אחריות state, כלים ופריסה.');
