insert into academy.entry_language_labels (entry_id,position,label) values ('pydantic-ai',0,'Python');
insert into academy.entry_sections (entry_id,position,title,body) values ('pydantic-ai',5,'הרחבה מאומתת — תפקיד ומסלול','פלט מטופס ותלויות מפורשות מקלים על בדיקות. Temporal, DBOS ו־Prefect הם אפשרויות תשתית שונות; validation מבני אינו הרשאה או אמת עובדתית.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pydantic-ai',6,'מגבלות ורישוי — עדכון','MIT לקוד נפרד מרישוי מנוע durability וספקי מודלים. שירות ושפה נוספים דורשים הצדקה לצוות .NET.');
