insert into academy.entry_sections (entry_id,position,title,body) values ('crewai',5,'הרחבה מאומתת — תפקיד ומסלול','Flows מגדירים זרימה ו־Crews מחלקים אחריות. התחילו בסוכן יחיד והוסיפו צוות רק כשיש אחריויות עצמאיות; שמרו checkpoints וגבולות פעולה מפורשים.');
