insert into academy.entry_sections (entry_id,position,title,body) values ('n8n',5,'הרחבה מאומתת — תפקיד ומסלול','טריגר מקבל אירוע, HTTP Request מפעיל פעולה עסקית וזרימה מטפלת בכשל ואישור. אין צורך במודל בכל שלב. n8n נשארת כלי מרכזי לתרגול, אך אין חובה להשתמש דווקא בה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('n8n',6,'מגבלות ורישוי — עדכון','Sustainable Use License ו־Enterprise אינם רישיון OSI גורף. בדקו מהדורה ותנאי שימוש גם כשמשתמש חיצוני מגדיר workflow דרך API או סוכן. סודות ונתוני executions דורשים ניהול.');
insert into academy.entry_sections (entry_id,position,title,body) values ('n8n',7,'השוואה ובחירת מסלול','בחרו כלי אינטגרציה אחד. Make/Zapier הם חלופות מנוהלות, Activepieces חלופת ליבה MIT ו־Windmill מסלול scripts.');
