insert into academy.entry_sections (entry_id,position,title,body) values ('temporal',5,'הרחבה מאומתת — תפקיד ומסלול','תהליך ארוך משחזר התקדמות לפי היסטוריה. קוד Workflow חייב לשמור דטרמיניזם; פעולות חיצוניות מבוצעות ב־Activities עם retries ו־idempotency.');
insert into academy.entry_sections (entry_id,position,title,body) values ('temporal',6,'מגבלות ורישוי — עדכון','SDK .NET ברישיון MIT; שירות Cloud או self-host דורש בחירת תפעול ותנאים נפרדים. Streams Preview עלולה לשנות API ותצורה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('temporal',7,'השוואה ובחירת מסלול','רשומה אחת משותפת ל־02 ול־03. למשימה קצרה Worker קטן מספיק; n8n לאינטגרציות ו־Windmill ל־scripts הם מסלולים שונים.');
insert into academy.sources(url) values ('https://docs.temporal.io/develop/dotnet') on conflict do nothing;
