insert into academy.entry_language_labels (entry_id,position,label) values ('pytorch',0,'Python');
insert into academy.entry_language_labels (entry_id,position,label) values ('pytorch',1,'C++ — LibTorch');
insert into academy.entry_sections (entry_id,position,title,body) values ('pytorch',5,'הרחבה מאומתת — תפקיד ומסלול','הפרידו נתונים, loss, עדכון פרמטרים, artifact והערכה. בחרו ערוץ Stable או Preview/nightly וחומרה מתאימה; אין כאן מספר שמוצג כגרסה האחרונה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pytorch',6,'מגבלות ורישוי — עדכון','רישיון PyTorch כולל תנאי הפצה והודעות; רישיונות מודלים ונתונים נבדקים בנפרד. אימון מוסיף משאבים ותפעול ואינו prerequisite ליישום LLM.');
insert into academy.entry_sections (entry_id,position,title,body) values ('pytorch',7,'השוואה ובחירת מסלול','PyTorch נשארת העשרה לקהל מפתחי יישומים. Transformers מקצרת שימוש ב־pretrained; TorchSharp ו־ML.NET הן התמחויות C#, לא דרישות נוספות.');
insert into academy.sources(url) values ('https://pytorch.org/get-started/locally/') on conflict do nothing;
insert into academy.entry_sources(entry_id,position,source_url,title,checked_at,supports) select e.id,coalesce((select max(position)+1 from academy.entry_sources where entry_id=e.id),0),'https://pytorch.org/get-started/locally/','PyTorch Start Locally','2026-11-03','Stable and Preview/nightly distinct; choose OS/compute platform. LibTorch C++ separate from .NET binding.' from academy.entries e where e.slug='pytorch' and not exists(select 1 from academy.entry_sources where entry_id=e.id and source_url='https://pytorch.org/get-started/locally/');
