insert into academy.category_guides (category_id,title,introduction,note) values ('11','מסלול התאמה — נתונים והערכה לפני אימון','קודם החליטו אם rules, prompt או RAG מספיקים. חובה להבין את העקרונות; אין חובה לאמן או לתרגל כל ספרייה.','TRL, TorchSharp ו־ML.NET הן התמחויות אופציונליות ואינן חלק אוטומטי מהמסלול המרכזי. אין צורך בכמה trackers, אימון RL או cluster לצורך התרגיל הראשון.');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('11',0,'training-mlops-fundamentals','הגדירו baseline, מדד ו־holdout לפני שינוי משקלים.','יסודות אימון');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('11',1,'hf-datasets','תעדו מקור, רישיון וגרסה והפרידו נתונים לפני preprocessing.','נתונים');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('11',2,'mlflow','תעדו ניסוי אחד עם config, metrics ו־artifact; קובץ metadata יכול להספיק להתחלה.','מעקב ניסוי');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('11',3,'hf-transformers','אם נדרשת התאמה, בחרו checkpoint מורשה ותרגיל אחד.','מודל מוכן');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('11',4,'hf-peft','בחנו LoRA רק לפי צורך ומדידה מול הבסיס.','התאמה לפי צורך');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('11',5,'inference-fundamentals','בדקו תאימות artifact, eval ו־rollback לפני בחירת serving.','הפרדת אימון והסקה');
insert into academy.category_guides (category_id,title,introduction,note) values ('00','מסלול יסוד — מהבעיה אל הכלי','מפת ידע לפני מוצר. אין צורך לתרגל את כל הקטגוריות; בחרו בעיה אחת ומסלול אחד.','RAG ב־04, הרצה עצמאית ב־08 ואימון ב־11 הם הסתעפויות לפי צורך. אין חובה להקים תשתית או ללמוד כל ספק.');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('00',0,'ai-ecosystem-fundamentals','הגדירו בעיה, baseline ושכבות מערכת לפני בחירת ספק.','מפת האקוסיסטם');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('00',1,'llm-fundamentals','הבינו tokens, הקשר והסקה; פלט אינו הרשאה לפעולה.','יסודות LLM');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('00',2,'hugging-face','קראו Model Card ורישיון checkpoint; אין חובה להשתמש ב־Inference Providers.','Hub ו־Model Cards');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('00',3,'tool-integration-fundamentals','תרגלו חוזה כלי קטן עם DTO והרשאה בשרת.','חוזי כלים');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('00',4,'ai-quality-security-fundamentals','הגדירו בדיקות ונתיב נתונים לפני הרחבת המערכת.','הערכה ואבטחה');
insert into academy.category_guides (category_id,title,introduction,note) values ('01','מסלול פיתוח — עוזר אחד ושינוי שנבדק','ליבה: משימה מוגבלת, עוזר אחד, diff ובדיקות. אין צורך לתרגל כל כלי; חלופות האטלס אינן שלבי חובה.','Cline, Antigravity, Devin Desktop ו־Aider זמינים להשוואה והתמחות בלבד. בחרו חלופה נוספת רק כדי לענות על שאלה מעשית; אין התקנה אוטומטית או חובת מעבר עורך.');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('01',0,'agentic-coding-fundamentals','כתבו reproduction, תנאי קבלה וגבולות פעולה.','יסודות פיתוח סוכני');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('01',1,'codex','בחרו עוזר אחד: Codex, Copilot, Claude Code או Cursor; אין חובה להשתמש דווקא ב־Codex. בצעו patch קטן.','תרגיל בעוזר אחד');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('01',2,'ai-quality-security-fundamentals','בדקו ולידציה בשרת, הרשאה חסרה ורגרסיה; סקרו diff לפני שמירה.','בדיקת התוצאה');
insert into academy.category_guides (category_id,title,introduction,note) values ('02','מסלול סוכנים — לולאה קטנה לפני תזמור','ליבה למפתח .NET: כלי אחד, מצב מפורש והערכה. בחרו stack אחד; אין צורך לתרגל כל framework.','Strands, Deep Agents ו־A2A הם הסתעפויות אופציונליות. Python/TypeScript ומנוע עמידות כגון Temporal נבחרים לפי צורך; AutoGen נשארת היסטורית.');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('02',0,'agent-systems-fundamentals','הגדירו לולאה, תקרת צעדים ואישור לפעולה עסקית.','יסודות סוכנים');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('02',1,'microsoft-extensions-ai','תרגלו abstraction קטן או לולאה ידנית ב־C# עם כלי קריאה.','גשר .NET');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('02',2,'microsoft-agent-framework','הוסיפו workflow רק כשהתכנון מצדיק זאת; בדקו כשל ואישור.','מסלול .NET');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('02',3,'langgraph','למדו state ו־checkpoint כהשוואת תכנון; אין חובה לשכתב את התרגיל לשפה נוספת.','מצב מפורש');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('02',4,'ai-quality-security-fundamentals','בדקו trace, הרשאות ו־eval לפני ריבוי סוכנים.','הערכת התהליך');
insert into academy.category_guides (category_id,title,introduction,note) values ('03','מסלול אוטומציה — אירוע אחד, פעולה אחת וטיפול בכשל','ליבה: חוזה אירוע וכלי אינטגרציה אחד. אין צורך לתרגל את כל הפלטפורמות או להוסיף מודל לכל זרימה.','Make, Zapier, Activepieces ו־Power Automate הם חלופות אופציונליות. Windmill היא בחירת C# scripts כשזו דרישה; אין חובת תרגול נוסף. לא הוקמה תשתית במסגרת הלימוד.');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('03',0,'workflow-automation-fundamentals','הגדירו מזהה עסקי, timeout ותגובה לכפילויות.','יסודות תהליכים');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('03',1,'n8n','תרגלו trigger→validation→draft בכלי אחד; אין חובה להשתמש דווקא ב־n8n.','אינטגרציה אחת');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('03',2,'ai-quality-security-fundamentals','בדקו כשל אחרי כתיבה, retry, הרשאה ואישור אנושי.','בדיקות תהליך');
insert into academy.category_guide_steps (category_id,position,entry_id,instruction,link_label) values ('03',3,'temporal','רק לתהליך ארוך או עמיד: תכננו Workflow/Activity ושחזור. אפשר לדלג כש־Worker קטן מספיק.','עמידות לפי צורך');
insert into academy.schema_migrations(version,description) values(14,'44 approved proposals: 26 additions, 13 corrections, five focused guides; two proposals deferred');
