begin isolation level serializable;
select pg_advisory_xact_lock(hashtext('academy-migrations'));
do $$ begin
 if (select max(version) from academy.schema_migrations) is distinct from 13 then raise exception 'Expected schema version 13'; end if;
 if (select count(*) from academy.entries)<>86 then raise exception 'Catalog changed since review'; end if;
 if exists(select 1 from academy.entries where id in ('ai-ecosystem-fundamentals','agentic-coding-fundamentals','github-copilot','cline','google-antigravity','devin-desktop','aider','agent-systems-fundamentals','microsoft-extensions-ai','strands-agents','deep-agents','a2a','workflow-automation-fundamentals','make','zapier','activepieces','windmill','power-automate','training-mlops-fundamentals','hf-transformers','hf-datasets','hf-peft','hf-trl','mlflow','torchsharp','ml-net') or slug in ('ai-ecosystem-fundamentals','agentic-coding-fundamentals','github-copilot','cline','google-antigravity','devin-desktop','aider','agent-systems-fundamentals','microsoft-extensions-ai','strands-agents','deep-agents','a2a','workflow-automation-fundamentals','make','zapier','activepieces','windmill','power-automate','training-mlops-fundamentals','hf-transformers','hf-datasets','hf-peft','hf-trl','mlflow','torchsharp','ml-net') or lower(name) in ('מפת האקוסיסטם של ai — יסודות ובחירת מסלול','פיתוח בעזרת סוכן — יסודות, הקשר, הרשאות וסקירה','github copilot','cline','google antigravity','devin desktop (לשעבר windsurf)','aider','מערכות סוכנים — יסודות, מצב ותזמור','microsoft.extensions.ai','strands agents','deep agents','agent2agent (a2a)','אוטומציה ותהליכים עמידים — יסודות','make','zapier','activepieces','windmill','microsoft power automate','אימון ו־mlops — יסודות, נתונים והערכה','hugging face transformers','hugging face datasets','hugging face peft','hugging face trl','mlflow','torchsharp','ml.net')) then raise exception 'Candidate identity already exists'; end if;
 if exists(select 1 from academy.repositories where lower(url) in ('https://github.com/cline/cline','https://github.com/aider-ai/aider','https://github.com/strands-agents/harness-sdk','https://github.com/langchain-ai/deepagents','https://github.com/a2aproject/a2a','https://github.com/activepieces/activepieces','https://github.com/windmill-labs/windmill','https://github.com/huggingface/transformers','https://github.com/huggingface/datasets','https://github.com/huggingface/peft','https://github.com/huggingface/trl','https://github.com/mlflow/mlflow','https://github.com/dotnet/torchsharp','https://github.com/dotnet/machinelearning')) then raise exception 'Candidate repository already represented'; end if;
 if exists(select 1 from academy.entries where lower(name) in ('windsurf','devin desktop','devin desktop / windsurf') or slug in ('windsurf','gemini-cli','wandb','wandb-models')) then raise exception 'Alias or deferred identity collision'; end if;
 if exists(select 1 from academy.repositories where lower(url)='https://github.com/strands-agents/sdk-python') then raise exception 'Strands alias already represented'; end if;
 if exists(select 1 from academy.category_guides where category_id in ('00','01','02','03','11')) then raise exception 'Reviewed guide changed'; end if;
 if (select document from academy.entry_documents where slug='codex') is distinct from '{"id":"codex","kind":"product","name":"Codex","slug":"codex","addedAt":"2026-10-31","example":"תרחיש לימודי: הוספת סינון לקטגוריה. מגדירים תוצאה בכתובת URL, משנים שכבה אחת בכל פעם ובודקים מקרה ריק, עברית וקלט לא תקין לפני Commit.","sources":[{"url":"https://learn.chatgpt.com/docs/glossary","title":"OpenAI — מילון המונחים של Codex","supports":"הגדרת Codex, לקוחות CLI/IDE ותפקיד AGENTS.md. שיטת העבודה והתרגיל הם המלצות לימודיות, לא טענות על ביצועים או על תוכנית תשלום.","checkedAt":"2026-10-31"}],"summary":"סוכן לפיתוח תוכנה: עבודה על משימה מוגדרת בהקשר של פרויקט, עם כלים ובקרת שינויים.","exercise":"בחר שינוי קטן. כתוב מטרה, שלושה תנאי קבלה ופעולות שדורשות אישור. לאחר המימוש השווה בין הבדיקות שביקשת לאלו שרצו בפועל; תוצר: סקירת Diff קצרה.","revision":2,"sections":[{"text":"Codex הוא סוכן הפיתוח של OpenAI. אפשר לעבוד איתו דרך לקוחות שונים, בהם CLI והרחבת IDE. הנושא כאן הוא תהליך פיתוח בעזרת סוכן; Agents SDK הוא נושא נפרד לבניית יישומי סוכנים.","title":"מה הוא פותר?"},{"text":"הגדר תוצאה ותנאי קבלה, ספק הקשר, בקש שינוי קטן ובדוק את ה־Diff ואת תוצאות הבדיקות. שמור נקודת Commit אחרי יחידת עבודה מובנת. זהו תהליך מומלץ, לא הבטחה שהסוכן ימצא כל טעות.","title":"מחזור עבודה מומלץ"},{"text":"התייחס לסוכן כאל שותף שמציע מימוש. האחריות לחוזה REST, למיגרציית SQL ולהתנהגות העסקית נשארת אצלך. שאל לא רק האם הקוד מתקמפל אלא מה הראיה שהוא נכון.","title":"החיבור לידע שלך"},{"text":"AGENTS.md נותן הוראות מתמשכות לפרויקט. לצדו כדאי להחזיק מצב, משימות והחלטות בקבצים. כך משימה חדשה יכולה להתחיל מהמציאות במאגר גם בלי כל היסטוריית השיחות.","title":"הקשר שאינו תלוי בשיחה"},{"text":"המלצה: הגדר מראש הרשאות לכתיבה, רשת ופעולות חיצוניות. בקשה לשינוי UI אינה הרשאה לפריסה. אל תכניס סודות למסמכי הפרויקט. זמינות יכולות ועלות נבדקות לפי סביבת העבודה והחשבון.","title":"הרשאות וגבולות"}],"verifiedAt":"2026-10-31","categoryIds":["01"],"addedAtBasis":"historical_backfill","relatedSlugs":["claude-code","cursor","openai-agents-sdk"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"Git, הרצת בדיקות וקריאת Diff.","alternativesNote":"Claude Code ו־Cursor הם מועמדים להשוואת תהליך פיתוח. השתמש באותה משימה ובאותן בדיקות, ומדוד גם זמן סקירה ותיקונים.","learningPriority":"must_learn","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"עבודה על מאגר C#, Python או TypeScript אינה SDK של המוצר בשפה זו. תמיכה בפיתוח קוד והטמעה תכנותית של סוכן הן שתי שאלות שונות."}'::jsonb then raise exception 'Reviewed document changed: codex'; end if;
 if (select document from academy.entry_documents where slug='claude-code') is distinct from '{"id":"claude-code","kind":"product","name":"Claude Code","slug":"claude-code","addedAt":"2026-10-31","example":"תרחיש לימודי: תיקון שגיאת ולידציה בטופס React וב־API. הצלחה מחייבת טיפול גם בבקשה ישירה לשרת, ולא רק במסך.","sources":[{"url":"https://code.claude.com/docs/en/overview","title":"Anthropic — Claude Code Overview","supports":"הגדרת הכלי, קריאת קוד, עריכה והרצת פקודות. תרחישי .NET ושיקולי הבחירה הם הצעות לימודיות.","checkedAt":"2026-10-31"}],"summary":"עוזר פיתוח סוכני שקורא מאגר, עורך קבצים ומריץ פקודות במסגרת סביבת העבודה שלו.","exercise":"נסח תיקון באג עם דרך שחזור ותוצאה צפויה. בקש קודם הסבר לסיבה ואז תיקון ממוקד. תוצר: Diff וראיה שהבאג שוחזר ונעלם, ללא שינויים שאינם קשורים.","revision":2,"sections":[{"text":"Claude Code מסייע במשימות פיתוח שדורשות הבנת קוד ושינוי מספר קבצים. התיעוד מציג עבודה במסוף, ב־IDE ובממשקים נוספים. הוא מוצר לפיתוח באמצעות AI, ולא מודל שפה בפני עצמו.","title":"איזו בעיה הוא פותר?"},{"text":"מחזור מומלץ: ניסוח הבעיה, קריאת האזורים הרלוונטיים, הצעת שינוי, הרצת בדיקות וסקירה אנושית. חשוב להפריד בין פקודה שהורצה לבין מסקנה עסקית שעדיין אינה מוכחת.","title":"איך ניגשים למשימה?"},{"text":"אפשר להגדיר משימת Endpoint עם תנאי קבלה ל־HTTP וללוגיקה. אל תסתפק בקומפילציה: בדוק הרשאות, מקרי קצה ושמירת נתונים. המתודולוגיה הזו אינה תלויה בשפת המאגר.","title":"החיבור ל־.NET"},{"text":"בדוק כיצד הכלי משתלב בתהליך הסקירה שלך, איזה הקשר הוא מקבל ואילו פעולות הוא מורשה לבצע. התאמה להרגלי עבודה חשובה לצד איכות ההצעה הראשונית.","title":"מה לבחון לפני בחירה?"},{"text":"המלצה: הרץ תרגול על נתוני דוגמה, הגבל הרשאות ובדוק פקודות חיצוניות לפני ביצוע. צריכת שימוש וזמינות יכולות תלויות בחשבון; אין כאן השוואת מחירים מאומתת.","title":"אבטחה ועלות"}],"verifiedAt":"2026-10-31","categoryIds":["01"],"addedAtBasis":"historical_backfill","relatedSlugs":["codex","cursor","mcp"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"Git, מסוף ובדיקות.","alternativesNote":"השווה ל־Codex או Cursor על אותו מאגר. המלצה: שקלל מספר תיקונים נדרשים ואיכות הבדיקות לצד זמן העבודה.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"קריאת קוד C#, Python או TypeScript אינה הוכחה ל־SDK רשמי בשפה. עמוד זה עוסק בכלי הפיתוח ולא ב־Anthropic SDK."}'::jsonb then raise exception 'Reviewed document changed: claude-code'; end if;
 if (select document from academy.entry_documents where slug='cursor') is distinct from '{"id":"cursor","kind":"product","name":"Cursor","slug":"cursor","addedAt":"2026-10-31","example":"תרחיש לימודי: הוספת מצב ללא תוצאות למסך חיפוש. בודקים את מצב ה־URL, הודעת המסך והתנהגות מקלדת לפני שמירת השינוי.","sources":[{"url":"https://cursor.com/docs/agent/overview","title":"Cursor — Agent Overview","supports":"כלי הסוכן, עריכת קבצים, פקודות וההבדל בין Checkpoints ל־Git. השיקולים והדוגמה נכתבו ללמידה.","checkedAt":"2026-10-31"}],"summary":"סביבת פיתוח עם סוכן המסייע לחקור קוד, לערוך קבצים ולהריץ בדיקות וכלים.","exercise":"בצע שינוי UI קטן ושחזור מקומי שלו, ואז שמור שינוי אחר ב־Git. תוצר: הסבר מה משוחזר בכל מנגנון ומה נשמר בהיסטוריית המאגר.","revision":2,"sections":[{"text":"Cursor משלב יכולות סוכן בתהליך הפיתוח. הסוכן יכול לחפש בקוד, לקרוא ולערוך קבצים ולהריץ פקודות. המודל הוא רכיב בתוך המוצר, והסביבה מספקת לו את ההקשר והכלים.","title":"איזו בעיה הוא פותר?"},{"text":"הגדר שינוי והתנהגות רצויה, תן לסוכן לחקור את המקומות הרלוונטיים ואז סקור את ההצעה. הרצת בדיקה צריכה לבדוק את הדרישה, לא רק להראות שהקוד החדש מסכים עם עצמו.","title":"זרימת עבודה"},{"text":"בתיקון React כדאי לבדוק בנפרד מצב רכיב, מעבר נתונים וקריאת REST. כלי שעורך כמה קבצים יכול לקצר עבודה, אך גבולות האחריות בין UI לשרת נשארים חלק מהתכנון שלך.","title":"החיבור לידע שלך"},{"text":"התיעוד מבחין בין Checkpoints מקומיים לשחזור שינויי הסוכן לבין Git לניהול גרסאות מתמשך. נקודת שחזור של כלי אינה תחליף ל־Commit שאפשר לשתף ולסקור.","title":"Checkpoint מול Git"},{"text":"המלצה: בדוק איזה מידע נשלח לשירותים, אילו פקודות מאושרות וכיצד מבטלים שינוי. לפני בחירת מסלול שימוש בדוק תנאים ומגבלות עדכניים; אין כאן דירוג מחיר או איכות.","title":"אבטחה ועלות"}],"verifiedAt":"2026-10-31","categoryIds":["01"],"addedAtBasis":"historical_backfill","relatedSlugs":["codex","claude-code"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"React או C#, Git וקריאת שגיאות.","alternativesNote":"Codex ו־Claude Code מציעים תהליכי פיתוח סוכניים נוספים. השווה על אותה דרישה ובדוק את ה־Diff הסופי.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"שפת הקוד שעליה עובדים אינה זהה לשפת SDK להטמעה. דף זה אינו קובע מטריצת תמיכה של הרחבות לכל שפה."}'::jsonb then raise exception 'Reviewed document changed: cursor'; end if;
 if (select document from academy.entry_documents where slug='microsoft-agent-framework') is distinct from '{"id":"microsoft-agent-framework","kind":"framework","name":"Microsoft Agent Framework","slug":"microsoft-agent-framework","addedAt":"2026-10-31","example":"תרחיש לימודי: סוכן בקשות ציוד מחלץ פריטים, בודק מלאי באמצעות פונקציית C# ומציג הצעה לאישור עובד מורשה לפני הזמנה.","sources":[{"url":"https://learn.microsoft.com/en-us/agent-framework/overview/","title":"Microsoft Learn — Agent Framework Overview","supports":"רכיבי המסגרת, Workflows, MCP, דוגמאות .NET/Python ופקודת חבילה עם prerelease. ארכיטקטורת הארגון והתרגיל הם הצעות שלנו.","checkedAt":"2026-10-31"}],"summary":"מסגרת לבניית סוכנים, כלים וזרימות עבודה, עם מסלול רשמי שמתאים למפתחי C#/.NET.","exercise":"שרטט שתי גרסאות לתרחיש מלאי: לולאה ידנית ומסגרת. תוצר: טבלה שמפרידה בין ניהול שיחה, הרצת כלים, הרשאות, בדיקות עסקיות ושמירת מצב.","revision":2,"sections":[{"text":"Microsoft Agent Framework מספקת רכיבי סוכן, חיבור לספקי מודלים וזרימות עבודה. התיעוד מציג לקוחות מודל, Sessions לניהול מצב, Middleware וחיבור לכלים ולשרתי MCP.","title":"מה היא פותרת?"},{"text":"תכנון אפשרי: React פונה ל־ASP.NET Core, שירות סוכן מפעיל מודל ופונקציות כלים קוראות ל־APIs ארגוניים. גבול הסוכן יכול להיות שירות בתוך אותו יישום, ללא צורך מיידי ב־Microservice.","title":"איך היא משתלבת בארגון?"},{"text":"המלצה: בנה תחילה לולאה ידנית קטנה: הודעה, בקשת כלי, ולידציה, ביצוע, החזרת תוצאה. אחר כך בדוק אילו חלקים המסגרת מנהלת ואילו כללים נשארים בקוד העסקי.","title":"מה ללמוד לפני ההפשטה?"},{"text":"התיעוד מציג Workflows שמחברים פונקציות וסוכנים בנתיבי ביצוע מפורשים. בעת הבחירה יש לבדוק את יכולות השפה והחבילה הספציפיות, במיוחד אישור אנושי והתאוששות.","title":"מצב וזרימות"},{"text":"המלצה: אכוף הרשאות בכלי, השתמש בפרטי משתמש מהשרת ושמור יומן פעולות. אל תבנה SQL מתוך הוראות המודל. עלות המודל ותפעול השירות נמדדים בנפרד.","title":"אבטחה ועלות"}],"verifiedAt":"2026-10-31","categoryIds":["02"],"addedAtBasis":"historical_backfill","relatedSlugs":["openai-agents-sdk","langgraph","mcp"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"C#, async/await, REST ולולאת קריאות כלים ידנית.","alternativesNote":"לולאה ידנית עם SDK של ספק, שירות TypeScript עם Agents SDK או שירות Python לפי צורך. אין חובה להוסיף שפה נוספת רק כדי להשתמש בסוכן.","learningPriority":"must_learn","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"נבדקו דוגמאות רשמיות ל־C#/.NET ול־Python. אין כאן הבטחת שוויון יכולות או יציבות חבילות; דוגמת .NET במקור משתמשת בדגל prerelease."}'::jsonb then raise exception 'Reviewed document changed: microsoft-agent-framework'; end if;
 if (select document from academy.entry_documents where slug='langgraph') is distinct from '{"id":"langgraph","kind":"framework","name":"LangGraph","slug":"langgraph","addedAt":"2026-10-31","example":"תרחיש לימודי: בקשת מלאי נעצרת אם חסרה כמות. לאחר הבהרה היא ממשיכה לבדיקה, ואז ממתינה לאישור לפני כתיבה למערכת הארגונית.","sources":[{"url":"https://docs.langchain.com/oss/python/langgraph/overview","title":"LangGraph — Overview","supports":"אורקסטרציה ברמה נמוכה, מצב, הרצה מתמשכת, אישור אנושי ואי־תלות ב־LangChain. תכנון המצבים וההמלצות הם לימודיים.","checkedAt":"2026-10-31"}],"summary":"אורקסטרציה מפורשת של זרימות וסוכנים בעלי מצב באמצעות גרף של שלבים ומעברים.","exercise":"שרטט חמישה מצבים ושני מסלולי שגיאה. תוצר: מצב שמור אחרי כל שלב, תנאי מעבר ותוכנית למניעת הזמנה כפולה לאחר ניסיון חוזר.","revision":2,"sections":[{"text":"LangGraph מתמקד באורקסטרציה של סוכנים ותהליכים מתמשכים בעלי מצב. הוא מאפשר לשלב צעדים דטרמיניסטיים וצעדים מונחי מודל באותה זרימה. לא חייבים להשתמש ב־LangChain כדי להשתמש בו.","title":"איזו בעיה הוא פותר?"},{"text":"מגדירים מצב משותף, פעולות שמשנות אותו וכללים שמחליטים לאן לעבור. למשל: קליטת בקשה, חילוץ נתונים, בדיקה, הבהרה ואישור. הזרימה מתארת מי רשאי לפעול ובאיזה תנאי.","title":"איך לחשוב על הזרימה?"},{"text":"כהקבלה לימודית: מצב הוא DTO מתמשך, שלב הוא Handler ומעבר מותנה דומה להחלטה במכונת מצבים. ההבדל החשוב הוא שחלק מהשלבים עשויים לכלול פלט לא ודאי ממודל.","title":"החיבור ל־C#"},{"text":"התיעוד מדגיש התמדה, הרצה מתמשכת ואדם בתהליך. בתכנון בפועל יש לבחור אחסון ולבדוק שחזור. פעולה חיצונית שכבר בוצעה דורשת מניעת כפילות גם כשהזרימה מתאוששת.","title":"עצירה והתאוששות"},{"text":"המלצה: כשצריך לראות הסתעפויות, המתנה לאישור והתאוששות במפורש. עבור בקשת מודל אחת, גרף עלול להוסיף קוד ותפעול בלי תועלת. מדוד סבבים, זמן ועלות לכל שלב.","title":"מתי זה מוצדק?"}],"verifiedAt":"2026-10-31","categoryIds":["02"],"addedAtBasis":"historical_backfill","relatedSlugs":["langchain","temporal","microsoft-agent-framework"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"מכונת מצבים, async, סוכן בסיסי והתמדה.","alternativesNote":"השווה ל־Microsoft Agent Framework עבור .NET, ל־Temporal לתהליך עמיד בקוד, או למכונת מצבים קטנה ביישום שלך.","learningPriority":"must_learn","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"עמוד זה אומת מול תיעוד Python. מימושים בשפות אחרות ופרטי התאימות שלהם מחייבים בדיקה נפרדת לפני בחירת חבילה."}'::jsonb then raise exception 'Reviewed document changed: langgraph'; end if;
 if (select document from academy.entry_documents where slug='langchain') is distinct from '{"id":"langchain","kind":"framework","name":"LangChain","slug":"langchain","addedAt":"2026-10-31","example":"תרחיש לימודי: סוכן מקבל בקשת ציוד, קורא לכלי מלאי ומחזיר הצעה. פונקציית הכלי משתמשת ב־API מורשה; המודל אינו מקבל חיבור חופשי למסד.","sources":[{"url":"https://docs.langchain.com/oss/python/langchain/overview","title":"LangChain — Overview","supports":"מודל, Harness, כלים, Middleware ויחס ל־LangGraph. ההקבלה ל־.NET והתרגיל הם שלנו.","checkedAt":"2026-10-31"},{"url":"https://docs.langchain.com/oss/javascript/langchain/overview","title":"LangChain — JavaScript Overview","supports":"קיום המימוש הרשמי ב־JavaScript/TypeScript ודוגמת יצירת סוכן.","checkedAt":"2026-10-31"}],"summary":"מסגרת להרכבת סוכן ממודל, כלים, הנחיות ו־Middleware, עם אינטגרציות לספקים.","exercise":"שרטט לולאה עם כלי אחד ושני מקרי כשל: פריט חסר וכשל רשת. תוצר: טבלת השלבים, מי אחראי לכל כשל ומתי מפסיקים לנסות.","revision":2,"sections":[{"text":"LangChain נותן רכיבים להרכבת יישומי סוכנים וחיבור מודלים וכלים. בתיעוד הנוכחי יצירת סוכן משלבת מודל עם Harness: ההנחיות, הכלים והשכבות שמנהלות את הלולאה.","title":"מה הוא פותר?"},{"text":"קלט מגיע לסוכן, המודל מבקש כלי, פונקציה מבצעת פעולה והתוצאה חוזרת ללולאה. אפשר להוסיף Middleware שישפיע על התנהגות ההרצה. פרטי ה־API תלויים בגרסה ובשפה.","title":"זרימת ההפעלה"},{"text":"כהקבלה לימודית, Middleware מזכיר שלבי Pipeline מסביב לפעולה. עם זאת, כאן ייתכנו כמה סבבי מודל וכלים בתוך בקשה אחת, ולכן צריך להגדיר גם גבול סבבים וזמן.","title":"החיבור ל־.NET"},{"text":"המלצה: בחר בו כשאינטגרציות והרכבת רכיבים חוסכות עבודה ממשית. ללולאה קטנה מול ספק יחיד כדאי להשוות גם מימוש ישיר כדי להבין מה ההפשטה מוסיפה.","title":"מתי לבחור?"},{"text":"כל כלי עדיין צריך הרשאה וולידציה בשרת. תכנן תקציב קריאות, טיפול בכשל ושמירת מצב. החלפת ספק אינה מבטיחה זהות בהתנהגות או בתמיכת הכלים.","title":"אבטחה ועלות"}],"verifiedAt":"2026-10-31","categoryIds":["02"],"addedAtBasis":"historical_backfill","relatedSlugs":["langgraph","openai-agents-sdk","pydantic-ai"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"לולאת קריאות כלים ידנית, async וחוזי קלט.","alternativesNote":"LangGraph מתאים לבחינת שליטה מפורשת בזרימה; Agents SDK או Pydantic AI הם מועמדים נוספים לפי שפה וצרכים.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"נבדקו דוגמאות רשמיות ל־Python ול־JavaScript/TypeScript. ב־C# אפשר לשלב שירות נפרד או לבחור מסגרת .NET; אין להניח תאימות של פורט קהילתי."}'::jsonb then raise exception 'Reviewed document changed: langchain'; end if;
 if (select document from academy.entry_documents where slug='openai-agents-sdk') is distinct from '{"id":"openai-agents-sdk","kind":"sdk","name":"OpenAI Agents SDK","slug":"openai-agents-sdk","addedAt":"2026-10-31","example":"תרחיש לימודי: סוכן שירות משתמש בכלי לקריאת סטטוס הזמנה. שינוי כתובת מוצג כהצעה נפרדת שהיישום מאשר לפני ביצוע.","sources":[{"url":"https://developers.openai.com/api/docs/guides/agents/sdk","title":"OpenAI — Agents SDK","supports":"SDKs רשמיים ב־Python/TypeScript ונושאי Runner, כלים ואורקסטרציה. ההמלצות והתרגיל נכתבו ללמידה.","checkedAt":"2026-10-31"},{"url":"https://developers.openai.com/api/docs/guides/agents","title":"OpenAI — Agent runtime options","supports":"הבחנה בין Agents API, Agents SDK ו־Responses API ואחריות היישום לאחסון, פריסה ואישורים.","checkedAt":"2026-10-31"}],"summary":"SDK לבניית סוכנים בתוך היישום שלך, עם Runner שמנהל לולאת סוכן והעברות בין סוכנים.","exercise":"תכנן סוכן עם כלי קריאה אחד. תוצר: חוזה כלי, תוצאת שגיאה, גבול סבבים ומקום שמירת השיחה. הסבר אילו חלקים היו קיימים גם ללא SDK.","revision":2,"sections":[{"text":"Agents SDK מספק מבנים להגדרת סוכנים, כלים וזרימות בתוך הקוד שלך. ה־Runner מטפל בלולאת הסוכן ובהעברות. OpenAI מבחינה בינו לבין Agents API המנוהל ובין עבודה ישירה עם Responses API.","title":"מה הוא פותר?"},{"text":"מגדירים סוכן וכלים, מפעילים Runner, מקבלים בקשות לכלים ותוצאה, ושומרים את המצב הנדרש להמשך. מתחילים בסוכן יחיד ומוסיפים העברות רק אם חלוקת האחריות מצדיקה אותן.","title":"זרימת עבודה"},{"text":"פריסה, אחסון, הרשאות ואינטגרציה עם הסביבה נשארים החלטות שלך. בדיקת קוד פריט והיתר לבצע הזמנה אינן נפתרות מעצם השימוש ב־SDK.","title":"מה נשאר באחריות היישום?"},{"text":"SDK לקריאות מודל ב־C# אינו בהכרח Agents SDK. אפשר ללמוד לולאה ידנית ב־C#, ואז להשוות לשירות Python או TypeScript, או למסגרת .NET מתאימה.","title":"החיבור ל־.NET"},{"text":"המלצה: הגבל כלים וסבבים, שמור עקבות ודרוש אישור לפני כתיבה חיצונית. חלוקת עבודה למספר סוכנים מחייבת מדידת עלות וזמן; היא אינה מבטיחה שיפור.","title":"אבטחה ועלות"}],"verifiedAt":"2026-10-31","categoryIds":["02"],"addedAtBasis":"historical_backfill","relatedSlugs":["microsoft-agent-framework","langchain","mcp"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"מודל, קריאות כלים, async ושמירת שיחה.","alternativesNote":"לולאה ידנית, LangChain, Pydantic AI או Microsoft Agent Framework. השווה שליטה במצב, הרשאות ובדיקות לצד כמות הקוד.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"התיעוד הרשמי שנבדק מפנה ל־SDKs ב־Python וב־TypeScript. אין להסיק מכך שקיים אותו SDK ב־C# או שכל יכולת זהה בין השפות."}'::jsonb then raise exception 'Reviewed document changed: openai-agents-sdk'; end if;
 if (select document from academy.entry_documents where slug='pydantic-ai') is distinct from '{"id":"pydantic-ai","kind":"sdk","name":"Pydantic AI","slug":"pydantic-ai","addedAt":"2026-10-31","example":"תרחיש לימודי: חילוץ בקשת רכש לטיפוס עם פריטים וכמויות. תוצאת החילוץ עוברת לבדיקה עסקית לפני שמירת טיוטה.","sources":[{"url":"https://pydantic.dev/docs/ai/overview/","title":"Pydantic AI — Overview","supports":"SDK Python מטופס, לולאת סוכן, תלויות ופלט. ההקבלות ל־.NET והפרדת הוולידציה הן הסבר הנדסי שלנו.","checkedAt":"2026-10-31"}],"summary":"SDK ב־Python שמדגיש טיפוסים, פלט מובנה ותלויות בתוך לולאת סוכן.","exercise":"הגדר מבנה של בקשת ציוד וארבע דוגמאות פלט: חסר, סוג שגוי, תקין מבנית ושגוי עסקית. תוצר: חלוקה בין ולידציה מבנית לבדיקות מערכת.","revision":2,"sections":[{"text":"Pydantic AI מציג לולאת סוכן עם טיפוסים ושילוב מודלים וכלים. הוא מתאים לבחינת תרחישים שבהם פלט הסוכן צריך להתאים למבנה נתונים ברור, לצד ניהול תלויות ובדיקות.","title":"איזו בעיה הוא פותר?"},{"text":"מגדירים קלט, תלויות וכלים, מפעילים סוכן ומקבלים תוצאה. מגדירים מה עושים כאשר פלט אינו עומד בחוזה. ניסיון חוזר חייב להיות מוגבל כדי שכשל לא יהפוך ללולאה יקרה.","title":"זרימת עבודה"},{"text":"כהקבלה לימודית, פלט מטופס מזכיר DTO וולידציה, ותלויות מזכירות Dependency Injection. ההתאמה אינה מלאה; חשוב ללמוד את המנגנון האמיתי במקום להניח שזה אותו Container.","title":"החיבור ל־C#"},{"text":"כמות יכולה להיות מספר חיובי והבקשה עדיין אסורה עסקית. אחרי בדיקה מבנית צריך לבדוק הרשאה, קיום פריט ומגבלות בארגון. גם תוצאה מטופסת יכולה להיות שגויה עובדתית.","title":"מה טיפוסים אינם מוכיחים?"},{"text":"המלצה: כש־Python וחוזי נתונים הם חלק מרכזי בשירות. במערכת .NET קטנה, הוספת שירות ושפה דורשת הצדקה. מדוד איכות פלט, תדירות ניסיונות חוזרים ועלות.","title":"מתי לבחור?"}],"verifiedAt":"2026-10-31","categoryIds":["02"],"addedAtBasis":"historical_backfill","relatedSlugs":["openai-agents-sdk","langchain","microsoft-agent-framework"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"Python בסיסי, טיפוסים, async וולידציה.","alternativesNote":"Agents SDK, LangChain או מסגרת .NET, לפי השפה והצורך. אפשר גם לממש חילוץ וולידציה בלי מסגרת סוכנים.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"התיעוד מתאר SDK ב־Python. חיבור מ־C# או TypeScript דרך שירות HTTP הוא בחירת ארכיטקטורה אפשרית, ולא SDK מקומי של Pydantic AI בשפות אלה."}'::jsonb then raise exception 'Reviewed document changed: pydantic-ai'; end if;
 if (select document from academy.entry_documents where slug='crewai') is distinct from '{"id":"crewai","kind":"framework","name":"CrewAI","slug":"crewai","addedAt":"2026-10-31","example":"תרחיש לימודי: צוות חוקר מקור רשמי ומנסח הצעת עדכון; Flow מעביר אותה לאדם. אין לכלי המחקר הרשאה לפרסם באתר.","sources":[{"url":"https://docs.crewai.com/v1.15.33/en/introduction","title":"CrewAI — Introduction","supports":"הבחנה בין Flows, Crews, תפקידים, משימות וזרימת אירועים. שיקולי המדידה והתרגיל הם שלנו.","checkedAt":"2026-10-31"}],"summary":"מסגרת שמשלבת Flows לניהול תהליך עם Crews לחלוקת משימות בין סוכנים בעלי תפקידים.","exercise":"חלק משימת מחקר לשני תפקידים ואז כתוב חלופה של סוכן יחיד. תוצר: מדדים להשוואת דיוק, זמן, עלות ומספר תיקוני האדם, כולל שלב איחוד.","revision":2,"sections":[{"text":"CrewAI מבדיל בין Flow, שמנהל מצב וזרימת ביצוע, לבין Crew, צוות סוכנים שעובד על משימות. אפשר להגדיר מטרות ותפקידים שונים ולהפעיל צוות בתוך שלב בתהליך.","title":"איזו בעיה הוא פותר?"},{"text":"אירוע מתחיל Flow, הזרימה מחליטה על הפעולה, צוות מבצע משימה ותוצאתו חוזרת לתהליך. תפקיד סמנטי כמו חוקר עדיין צריך קלט, פלט וקריטריון הצלחה מוגדרים.","title":"זרימת עבודה"},{"text":"כהקבלה: Flow מזכיר מנהל תהליך, ו־Crew יחידת ביצוע. אל תבלבל בין שם תפקיד בפרומפט לבין הרשאות שרת אמיתיות. שני סוכנים יכולים לחלוק את אותה טעות.","title":"החיבור לידע שלך"},{"text":"המלצה: לאחר שתרחיש עם סוכן יחיד עובד ויש משימות עצמאיות שמצדיקות חלוקה. השווה תוצאה על אותו סט בדיקות; קח בחשבון גם עלות תקשורת, איחוד ותיקון סתירות.","title":"מתי להשתמש?"},{"text":"מגדירים גבול משימות וסבבים, כלים לפי אחריות ואישור אנושי לפני פרסום. בודק שמבוסס על מודל מסייע לסקירה, אך אינו מחליף ראיות או בדיקות דטרמיניסטיות.","title":"בקרת איכות ואבטחה"}],"verifiedAt":"2026-10-31","categoryIds":["02"],"addedAtBasis":"historical_backfill","relatedSlugs":["langgraph","pydantic-ai","temporal"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"סוכן יחיד, מצב, כלים ומדידת תוצאות.","alternativesNote":"אפשר להתחיל בסוכן יחיד עם לולאה מפורשת או לבחור LangGraph לניהול גרף. תהליך שמורכב מחוקים עשוי להתאים ל־Temporal ללא צוות סוכנים.","learningPriority":"enrichment","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"המסלול המתואר במפת הלמידה הוא Python. מטריצת SDKs עדכנית לא אומתה כאן; לפני התקנה בדוק חבילה ושפה בתיעוד הייעודי."}'::jsonb then raise exception 'Reviewed document changed: crewai'; end if;
 if (select document from academy.entry_documents where slug='mastra') is distinct from '{"id":"mastra","kind":"framework","name":"Mastra","slug":"mastra","addedAt":"2026-11-02","example":"דוגמה לימודית מוצעת, שלא הורצה כאן: מסך React שולח פנייה לשירות Mastra. Workflow מאחזר סטטוס הזמנה מ־API של .NET, מבקש מהמודל ניסוח תשובה ומחזיר טיוטה לבדיקה. זיכוי כספי אינו מבוצע מתוך הטיוטה אלא לאחר אישור ופקודת שרת נפרדת.","sources":[{"url":"https://mastra.ai/docs","title":"Mastra — תיעוד רשמי","supports":"תפקיד, מבנה ותמיכת שפות; טענות על היעדר SDK מוגבלות למקורות שנבדקו.","checkedAt":"2026-11-02"},{"url":"https://github.com/mastra-ai/mastra","title":"Mastra — GitHub רשמי","supports":"זהות המאגר, קוד ומצב הפרויקט.","checkedAt":"2026-11-02"},{"url":"https://mastra.ai/blog/the-next-million-ai-developers","title":"Mastra — הכרזה ציבורית","supports":"ההכרזה הציבורית של Mastra מ־20 בנובמבר 2024. אין לבלבל עם השקת beta ב־2025 או גרסת 1.0 מאוחרת יותר.","checkedAt":"2026-11-02"}],"summary":"מסגרת TypeScript לבניית יישומי AI וסוכנים, עם כלים, תהליכי עבודה, זיכרון, הערכה ותצפיתיות. מיועדת לצוותי מוצר שרוצים לכתוב את שכבת הסוכנים באקוסיסטם Node.js.","exercise":"הגדירו שלושה צעדים: שליפת הזמנה, יצירת טיוטה ואישור. תכננו מה נשמר כשאחד השלבים נכשל, ובדקו בקשה ללא הרשאה. השוו למימוש המקביל ב־OpenAI Agents SDK.","revision":1,"sections":[{"text":"Mastra מאגדת בניית סוכן, כלים ו־Workflows ב־TypeScript. שימושים מרכזיים הם עוזרי מוצר, עיבוד בקשות ותהליכים שמשלבים קריאות מודל עם צעדים עסקיים מפורשים.","title":"איזו בעיה היא פותרת?"},{"text":"מגדירים Agent וכלים עם סכמות קלט, ומרכיבים צעדים ב־Workflow לפי הצורך. זיכרון, אחסון ו־traces הם רכיבים בעלי אחריות נפרדת. כלי שקורא REST דומה למתאם שירות ב־C#; חוקי הדומיין ממשיכים להיאכף בשרת המוסמך.","title":"איך בנויה ההרצה?"},{"text":"עוזר תמיכה בתוך יישום React, יצירת טיוטת תשובה עם מידע ארגוני ותהליך שצריך לעצור לאישור. היכולת לצפות בהרצה ולהעריך פלטים אינה ערובה לנכונות; יש להכין מקרי בדיקה עסקיים.","title":"שימושים מרכזיים"},{"text":"השוואה פדגוגית: Mastra מתאימה לבחינת חבילה משולבת לצוות TypeScript. השוו ל־LangGraph כשחשובה שליטה בגרף, ול־OpenAI Agents SDK כשרוצים לולאת סוכן ממוקדת. מול Microsoft Agent Framework שקלו האם נכון להשאיר את השרת ב־C#.","title":"מתי לבחור ובמה להשוות?"},{"text":"אל תעבירו סודות לדפדפן React ואל תתנו לכלי גישה חופשית למסד. יש לאמת משתמשים גם כשהסוכן חשוף כ־API. יכולות תלויות בגרסה, ולכן דוגמאות ישנות דורשות התאמה לתיעוד הנוכחי.","title":"גבולות ובטיחות"}],"approvedAt":"2026-11-02","verifiedAt":"2026-11-02","categoryIds":["02"],"addedAtBasis":"approved_proposal","discoveredAt":"2026-11-02","relatedSlugs":["langgraph","openai-agents-sdk","microsoft-agent-framework"],"revisionNote":"מקורות רשמיים נבדקו ב־2026-11-02; דוגמאות, תרגילים והשוואות מסומנים כפדגוגיים ולא הורצו. אין אימות מעבדתי לכל API.","prerequisites":"היכרות עם REST/JSON, אימות קלט, לולאת tool calling והפרדת לוגיקה עסקית מהמודל.","alternativesNote":"LangGraph ו־OpenAI Agents SDK הן חלופות קיימות לבחינת תזמור סוכן ב־TypeScript. Microsoft Agent Framework מתאים יותר לבחינת מימוש מקומי ב־C#; אין להסיק עדיפות מנתוני GitHub בלבד.","learningPriority":"should_know","approvalReference":"User request 2026-11-02: add ADK, Mastra, smolagents, Agno and Legacy AutoGen; docs/DECISIONS.md D-029","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"TypeScript היא שפת המסגרת הרשמית באקוסיסטם JavaScript/Node.js. אין כאן SDK Python או C#/.NET מקומי מאומת. אפשר לחשוף שירות Mastra מאומת ולצרוך את ה־API מ־C# או Python; הלקוח אינו הופך את שפת הצריכה לשפת המסגרת."}'::jsonb then raise exception 'Reviewed document changed: mastra'; end if;
 if (select document from academy.entry_documents where slug='n8n') is distinct from '{"id":"n8n","kind":"platform","name":"n8n","slug":"n8n","addedAt":"2026-10-31","example":"תרחיש לימודי: הודעת בקשת ציוד נקלטת, נתוניה נבדקים, נפתחת טיוטה ונשלחת לאישור. קריאת AI נדרשת רק אם הקלט חופשי.","sources":[{"url":"https://docs.n8n.io/","title":"n8n — Documentation","supports":"הגדרת כלי אוטומציה עם יכולות AI ואפשרויות ענן/אירוח עצמי. תכנון השלבים והתרגיל הם שלנו; מחירים ותכונות מסלול לא אומתו.","checkedAt":"2026-10-31"}],"summary":"כלי אוטומציה לחיבור פעולות עסקיות ויכולות AI לתהליך עבודה.","exercise":"תכנן רצף בקשה ← בדיקה ← טיוטה. תוצר: חוזה JSON, מסלול כשל ודרך לזהות הודעה כפולה. סמן איזה שלב דורש מודל ואיזה הוא חוק רגיל.","revision":2,"sections":[{"text":"n8n מחבר אוטומציה עסקית ויכולות AI. במקום לפתח כל אינטגרציה מאפס, מרכיבים תהליך סביב מקורות קלט, פעולות והעברת נתונים. לא כל תהליך דורש מודל או סוכן.","title":"מה הוא פותר?"},{"text":"המלצה: התחל מטריגר אחד, מעבר נתונים מפורש ותוצאה אחת. בכל שלב הגדר איזה JSON נכנס, מה יוצא ומה עושים בכשל. בדוק את התהליך עם נתוני דוגמה לפני חיבור למערכת אמיתית.","title":"איך מתכננים תהליך?"},{"text":"הקבלה לימודית: רצף פעולות מזכיר Pipeline שקורא לכמה שירותי REST. ממשק חזותי אינו מבטל צורך בחוזים, טיפול ב־null או הבנה אם פעולה כבר בוצעה.","title":"החיבור לידע שלך"},{"text":"שקול שירות ייעודי כשהלוגיקה העסקית, הבדיקות או ההרשאות נעשות מורכבות. אפשר להשאיר את התזמור ב־n8n ולחשוף פעולה עסקית אחת דרך API מאומת.","title":"מתי קוד נפרד עדיף?"},{"text":"התיעוד מציע מסלול ענן וגם אירוח עצמי. בדוק רישוי, תחזוקה, גיבויים ומחיר לפני בחירה. שמור אישורים מחוץ לזרימות המיוצאות והימנע משמירת מידע רגיש בלוגים.","title":"אירוח, אבטחה ועלות"}],"verifiedAt":"2026-10-31","categoryIds":["03"],"addedAtBasis":"historical_backfill","relatedSlugs":["temporal","dify","mcp"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"REST, JSON, אירועים והרשאות.","alternativesNote":"Make, Zapier או Activepieces מוזכרים במפת הידע כמועמדים לבדיקה. Temporal הוא חלופה לתזמור בקוד כשהעמידות היא דרישה מרכזית.","learningPriority":"must_learn","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"זהו כלי אוטומציה, לא SDK סוכנים ב־C#. שירותי C#, Python ו־TypeScript יכולים להשתלב דרך APIs; תמיכת קוד בתוך הזרימה תלויה בגרסה ובסביבה ולא אומתה כאן."}'::jsonb then raise exception 'Reviewed document changed: n8n'; end if;
 if (select document from academy.entry_documents where slug='temporal') is distinct from '{"id":"temporal","kind":"orchestration_engine","name":"Temporal","slug":"temporal","addedAt":"2026-10-31","example":"תרחיש לימודי: תהליך רכש בודק מלאי, ממתין לאישור ומבצע הזמנה. כשל של Worker בזמן ההמתנה אינו צריך למחוק את התהליך העסקי.","sources":[{"url":"https://docs.temporal.io/workflows","title":"Temporal — Workflows","supports":"Workflow Definition/Execution, היסטוריית אירועים, Replay ודרישת עקביות. הדוגמה ושיקולי הבחירה הם שלנו.","checkedAt":"2026-10-31"},{"url":"https://docs.temporal.io/develop","title":"Temporal — SDKs","supports":"קיום מסלולי SDK רשמיים ל־.NET, Python ו־TypeScript.","checkedAt":"2026-10-31"}],"summary":"פלטפורמה להרצת תהליכים עמידים בקוד, עם היסטוריית אירועים ושחזור מצב לאחר כשל.","exercise":"הגדר איזה מידע צריך לשרוד בכל נקודה. תוצר: גבול Workflow/Activity, מפתח למניעת כפילות והסבר מה קורה כשהשרת נופל אחרי ביצוע הזמנה ולפני קבלת תשובה.","revision":2,"sections":[{"text":"תהליך יכול להימשך מעבר לבקשת HTTP או לחיי תהליך שרת. Temporal שומר היסטוריית אירועים המאפשרת להחזיר Workflow למצבו ולהמשיך לאחר כשל תשתיתי.","title":"איזו בעיה היא פותרת?"},{"text":"הגדרת Workflow היא קוד; Execution היא הרצה מסוימת. בשחזור, הקוד משתמש בהיסטוריה שנרשמה כדי לשחזר את ההתקדמות. לכן ההחלטות ב־Workflow צריכות להיות עקביות עם אותה היסטוריה.","title":"מה קורה בשחזור?"},{"text":"קריאות רשת ותוצאות משתנות אינן צריכות להתרחש באקראי בתוך קוד שנבנה מחדש. תכנן אותן כ־Activities והגדר טיפול בניסיונות חוזרים. שירות חיצוני עדיין צריך לזהות פעולות כפולות.","title":"פעולות חיצוניות"},{"text":"אפשר להשוות למנהל תהליך עמיד מעל שירותים עסקיים. ה־Workflow מגדיר סדר והמתנה, והפעולות מבצעות עבודה. תכנון כזה שונה מלהחזיק בקשת ASP.NET פתוחה עד שאדם יאשר.","title":"החיבור ל־.NET"},{"text":"המלצה: תהליך הזמנה או מחקר שצריך לשרוד כשל והמתנה. למשימה קצרה יחידה, Worker קטן עשוי להספיק. העלות כוללת גם שירות תזמור, Workers וניטור.","title":"מתי זה מוצדק?"}],"verifiedAt":"2026-10-31","categoryIds":["03","02"],"addedAtBasis":"historical_backfill","relatedSlugs":["n8n","langgraph"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"async, תורים, כשלי רשת ו־Idempotency.","alternativesNote":"Worker ותור עם מצב שמור, או n8n לתהליך אינטגרציה. LangGraph נבחן כשמרכז הכובד הוא זרימת סוכן; אין זהות אוטומטית בין המוצרים.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"דף ה־SDKs הרשמי מציג .NET, Python ו־TypeScript. פרטי API ותאימות נבדקים לפי גרסת החבילה; זה אינו SDK של מודל."}'::jsonb then raise exception 'Reviewed document changed: temporal'; end if;
 if (select document from academy.entry_documents where slug='pytorch') is distinct from '{"id":"pytorch","kind":"framework","name":"PyTorch","slug":"pytorch","addedAt":"2026-10-31","example":"תרחיש לימודי: מסווג קטן לתמונות או לטקסט דוגמה. היישום העסקי צורך את תוצאת ההסקה דרך גבול מוגדר, בנפרד מתהליך האימון.","sources":[{"url":"https://docs.pytorch.org/tutorials/beginner/basics/intro.html","title":"PyTorch — Learn the Basics","supports":"מחזור ML, נתונים, מודל, אופטימיזציה ושמירה במדריך Python. שיקולי הבחירה וההקבלות לפיתוח יישומים הם שלנו.","checkedAt":"2026-10-31"}],"summary":"מסגרת ללמידת מכונה: נתונים, Tensors, מודלים, אופטימיזציה ושמירת תוצרי אימון.","exercise":"קרא את מדריך היסודות ושרטט נתונים ← מודל ← שגיאה ← עדכון ← הערכה. תוצר: הסבר מה נשמר לפריסה ואיך תזהה ניסוי שמצליח באימון אך נכשל בהערכה.","revision":2,"sections":[{"text":"PyTorch מספקת אבני בניין לעבודה עם נתונים, בניית מודלים, אופטימיזציה ושמירת מודל מאומן. היא נמצאת בשכבת למידת המכונה, ולא מחליפה API עסקי, מסד נתונים או מסגרת סוכנים.","title":"איזו בעיה היא פותרת?"},{"text":"מכינים נתונים, מגדירים מודל, מחשבים שגיאה, מעדכנים פרמטרים ובודקים תוצאות. בתהליך טיפוסי מפרידים נתוני אימון והערכה כדי לבדוק יכולת הכללה, לא רק זכירת דוגמאות.","title":"מחזור עבודה"},{"text":"כהקבלה: קוד תוכנית רגיל מגדיר כללים במפורש; באימון מגדירים מבנה ומטרה ומפיקים פרמטרים מהנתונים. גם כאן יש צורך בגרסאות, בדיקות ותיעוד קלט ופלט.","title":"החיבור לידע שלך"},{"text":"המלצה: אם מודל קיים עם הוראות או אחזור ידע פותר את הבעיה, התחל ממנו. אימון והתאמה מוסיפים אחריות לנתונים, איכות, משאבים ומחזור חיים.","title":"למה לא להתחיל כאן?"},{"text":"שמור גרסת נתונים, הגדר מדד והפרד ניסוי מהפעלה עסקית. חומרה ותלויות תלויות בסביבת האימון. מודל שסווג היטב במדגם קטן אינו מוכיח התאמה לייצור.","title":"תפעול ואיכות"}],"verifiedAt":"2026-10-31","categoryIds":["11"],"addedAtBasis":"historical_backfill","relatedSlugs":["llm-fundamentals","hugging-face","ollama"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"Python, אלגברה בסיסית והפרדה בין אימון להסקה.","alternativesNote":"שימוש במודל קיים, RAG או שירות הסקה מנוהל הם חלופות לשינוי פרמטרים כשמטרת העסק מאפשרת זאת. אין צורך ללמוד אימון מלא לפני בניית יישום AI ראשון.","learningPriority":"enrichment","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"מדריך היסודות שנבדק משתמש ב־Python. חיבור תוצר למערכת C# או TypeScript הוא החלטת פריסה נפרדת; אין כאן מטריצת Runtime מאומתת."}'::jsonb then raise exception 'Reviewed document changed: pytorch'; end if;
end $$;
