update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה: תקנו ולידציה בטופס React וב־ASP.NET endpoint: הגדירו שלושה תנאי קבלה, גבולות כתיבה ובדיקת בקשה ישירה לשרת. סקרו diff והריצו בדיקות לפני שמירה או פרסום.',exercise='תעדו גרסה, חוזה ותנאי קבלה לתרחיש. בדקו קלט חסר, הרשאה חסרה וכשל באמצע; השוו לחלופה אחת בלבד. אין צורך לתרגל כל כלי בקטלוג.',language_support_note='אפשר לעבוד על קוד C# ו־React; הרצת dotnet build/test דורשת SDK ותלויות בסביבת העבודה. עריכת C# אינה SDK .NET של העוזר. Codex אינו SDK סוכנים ליישום.',alternatives_note='אין חובה בעוזר מסוים: Copilot מתאים לבחינת Visual Studio, Claude Code למסלול סוכני ו־Cursor להשוואת IDE. בחרו אחד לתרגיל המרכזי.' where entry_id='codex';
